const SB_URL = 'https://qwcfsqsrtegyvvwkzcgb.supabase.co/rest/v1'
const SB_KEY = 'sb_publishable_mi9rS5i9a-xrAWC0lG0TNA_vg903xRL'

async function sbFetch(path, opts = {}) {
  const res = await fetch(SB_URL + path, {
    ...opts,
    headers: {
      apikey: SB_KEY,
      Authorization: 'Bearer ' + SB_KEY,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
      ...(opts.headers || {})
    },
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined
  })
  if (!res.ok) {
    let msg = res.statusText
    try { const j = await res.json(); msg = j.message || j.hint || JSON.stringify(j) } catch {}
    throw new Error(msg)
  }
  if (res.status === 204) return null
  return res.json()
}
const sbGet  = p     => sbFetch(p)
const sbPost = (p,b) => sbFetch(p, { method:'POST', body:b })
const sbPatch= (p,b) => sbFetch(p, { method:'PATCH', body:b })
const sbDel  = p     => sbFetch(p, { method:'DELETE', headers:{ Prefer:'' } })
const sbUpsert = (p,b) => sbFetch(p, { method:'POST', body:b, headers:{ Prefer:'resolution=merge-duplicates,return=representation' } })

/* — ID Generator ————————————————————————————— */
async function generateAssetId() {
  const res = await sbGet('/ss_items?select=id&order=created_at.desc&limit=300') || []
  const max = res.reduce((m, r) => {
    const n = parseInt(String(r.id).replace('SS-',''), 10)
    return isNaN(n) ? m : Math.max(m, n)
  }, 0)
  return 'SS-' + String(max + 1).padStart(4, '0')
}

async function generateTradeCode() {
  const res = await sbGet('/ss_item_events?select=trade_code&trade_code=not.is.null&order=timestamp.desc&limit=500') || []
  const max = res.reduce((m, r) => {
    const n = parseInt(String(r.trade_code).replace('T-',''), 10)
    return isNaN(n) ? m : Math.max(m, n)
  }, 0)
  return 'T-' + String(max + 1).padStart(4, '0')
}

async function generatePbCode() {
  const res = await sbGet('/ss_items?select=pb_code&pb_code=not.is.null&order=created_at.desc&limit=500') || []
  const max = res.reduce((m, r) => {
    const n = parseInt(String(r.pb_code).replace('PB-',''), 10)
    return isNaN(n) ? m : Math.max(m, n)
  }, 0)
  return 'PB-' + String(max + 1).padStart(4, '0')
}

/* — Helpers ————————————————————————————————— */
function h(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;') }
function isBanned(set, name) { return !!(set && name && set.has(String(name).toLowerCase())) }

const PERSONAL_USE_NOTE = 'BC kept for personal use'
function notesWithPersonalUseMarker(notes, shouldHaveMarker) {
  const base = (notes||'').split(' | ').map(s=>s.trim()).filter(s=>s && s!==PERSONAL_USE_NOTE)
  if (shouldHaveMarker) base.push(PERSONAL_USE_NOTE)
  return base.join(' | ') || null
}

function fmtWorth(n) { return Math.round((n||0)/1000).toLocaleString() }
function fmtWorthK(n) {
  if (n == null) return '0'
  const abs = Math.abs(n)
  if (abs < 1000) return n.toLocaleString()
  return (n/1000).toLocaleString(undefined,{maximumFractionDigits:1}) + 'K'
}

function relTime(iso) {
  if (!iso) return '—'
  const diff = (Date.now() - new Date(iso)) / 1000
  if (diff < 60) return 'just now'
  if (diff < 3600) return Math.floor(diff/60)+'m ago'
  if (diff < 86400) return Math.floor(diff/3600)+'h ago'
  if (diff < 604800) return Math.floor(diff/86400)+'d ago'
  return fmtDate(iso)
}

function fmtDate(iso, short) {
  if (!iso) return '—'
  const d = new Date(iso)
  if (short) return d.toLocaleDateString('nl-NL',{day:'2-digit',month:'short'})
       + ' ' + d.toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})
  return d.toLocaleDateString('nl-NL',{day:'2-digit',month:'short',year:'numeric'})
       + ' ' + d.toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})
}

function statusBadge(s) {
  const m = {active:['badge-green','In Inventory'],traded:['badge-orange','Ready for Pullback'],pullbacked:['badge-red','Pulled Back'],lost:['badge-zinc','Lost']}
  const [cls,label] = m[s] || ['badge-zinc', s||'?']
  return `<span class="badge ${cls}">${label}</span>`
}

// Clickable status badge for the Pullbacks table — Ready for Pullback ↔ Pulled Back is a
// quick, common toggle that shouldn't need the full Edit Asset modal every time. 'lost'
// stays a plain badge (not part of that toggle).
let _quickStatusOpenId = null
function quickStatusBadge(a) {
  if (a.current_status !== 'traded' && a.current_status !== 'pullbacked') return statusBadge(a.current_status)
  const m = {traded:['badge-orange','Ready for Pullback'],pullbacked:['badge-red','Pulled Back']}
  const [cls,label] = m[a.current_status]
  const open = _quickStatusOpenId === a.id
  return `<span style="position:relative;display:inline-block">
    <button class="badge ${cls}" style="cursor:pointer;appearance:none;-webkit-appearance:none;margin:0;font-family:inherit;line-height:inherit" data-action="quick-status-toggle" data-id="${h(a.id)}">${label}</button>
    <div class="ac-dropdown" id="qs-dd-${h(a.id)}" style="display:${open?'block':'none'};min-width:150px">
      <div class="ac-item" data-action="quick-status-set" data-id="${h(a.id)}" data-holder="${h(a.current_holder)}" data-new-status="traded">Ready for Pullback</div>
      <div class="ac-item" data-action="quick-status-set" data-id="${h(a.id)}" data-holder="${h(a.current_holder)}" data-new-status="pullbacked">Pulled Back</div>
    </div>
  </span>`
}

/* — Item catalog (photos + trade values) ——————————————— */
let _catalogImagesLoaded = false
window._catalogImages = window._catalogImages || {}
window._catalogValues = window._catalogValues || {}
async function ensureCatalogImages() {
  if (_catalogImagesLoaded) return
  try {
    const rows = await sbGet('/ss_item_catalog?select=item_name,image_url,value') || []
    const imgMap = {}, valMap = {}
    rows.forEach(r => { if (r.image_url) imgMap[r.item_name] = r.image_url; if (r.value!=null) valMap[r.item_name] = r.value })
    window._catalogImages = imgMap
    window._catalogValues = valMap
  } catch (e) { /* table may not exist yet */ }
  _catalogImagesLoaded = true
}
function itemThumb(name) {
  const url = (window._catalogImages||{})[name]
  return url ? `<img class="row-thumb" src="${h(url)}" alt="">` : `<span class="row-thumb-ph"></span>`
}

function tradeItemRow(name) {
  return `<div style="display:flex;align-items:center;gap:6px">
    ${itemThumb(name)}
    <span style="color:var(--text);font-size:12px;white-space:nowrap">${h(name)}</span>
  </div>`
}

const EV_LABELS = {manual_update:'Update',marketplace_sale:'New Trade',trade:'Trade',pullback:'Marked as Pulled Back',dupe:'New Pullback'}
const REASON_LABELS = {
  CREATED:'New Item in Inventory',
  DUPED_LOG:'New Duped Item',
  RECOVERED:'Recovered Item',
  HOLDER_CHANGE:'Moved',
  LOST:'Marked as Lost',
  RESTORED:'Marked as Restored',
  IMPORTED:'New Item in Inventory',
  EDITED:'Edited'
}
const EV_COLORS = {manual_update:'var(--primary)',marketplace_sale:'var(--red)',trade:'var(--primary)',pullback:'var(--orange)',dupe:'var(--orange)'}
const REASON_COLORS = {CREATED:'var(--green)',DUPED_LOG:'var(--orange)',RECOVERED:'var(--green)',HOLDER_CHANGE:'var(--zinc)',LOST:'var(--zinc)',RESTORED:'var(--green)',IMPORTED:'var(--green)',EDITED:'var(--primary)'}

function eventBadge(t, reason, scamType) {
  let label, col
  if (t==='marketplace_sale') {
    // Always the specific scam type ("New Gambled", "New Hacked", ...) — no more
    // generic "New Bulk Traded" wording regardless of how many items were involved.
    const typeLabel = SCAM_TYPE_LABELS[scamType] || SCAM_TYPE_LABELS.traded
    label = `New ${typeLabel}`
    col = SCAM_TYPE_COLORS[scamType] || SCAM_TYPE_COLORS.traded
  } else if (reason && REASON_LABELS[reason]) {
    label = REASON_LABELS[reason]
    col = REASON_COLORS[reason] || EV_COLORS[t] || 'var(--muted)'
  } else {
    label = EV_LABELS[t] || t || '?'
    col = EV_COLORS[t] || 'var(--muted)'
  }
  return `<span style="display:inline-flex;align-items:center;gap:4px;font-size:10px;font-weight:700;color:${col}"><span style="display:inline-block;width:6px;height:6px;border-radius:50%;background:${col};flex-shrink:0"></span>${label}</span>`
}

function dotColor(t) {
  return EV_COLORS[t]||'var(--muted)'
}

/* — Tag-list helper (given/received items etc.) ——————————— */
function tagList(items, colorVar) {
  if (!items || !items.length) return '<span class="text-muted">—</span>'
  return items.map(i=>`<span style="display:inline-block;padding:1px 6px;border-radius:3px;background:color-mix(in oklch,var(${colorVar}) 12%,transparent);color:var(${colorVar});border:1px solid color-mix(in oklch,var(${colorVar}) 25%,transparent);font-size:10px;margin:1px">${h(i)}</span>`).join('')
}
function parseItemList(str) {
  if (!str) return []
  const m = str.match(/^Items:\s*(.+)/m)
  const src = m ? m[1] : str
  return src.split(',').map(s=>s.trim()).filter(Boolean)
}

/* — Router ————————————————————————————————— */
function nav(r) {
  const newHash = '#' + r
  if (window.location.hash === newHash) route()
  else window.location.hash = newHash
}

function updateNav(view) {
  document.querySelectorAll('.nav-item').forEach(el => {
    const r = el.dataset.route
    const active = r === view || (view === 'asset' && r === 'pullbacks') || (view === 'invlog' && r === 'inventory')
    el.classList.toggle('active', active)
    const dot = el.querySelector('.dot'); if (dot) dot.remove()
    if (active) el.insertAdjacentHTML('beforeend','<span class="dot"></span>')
  })
}

async function route() {
  const hash = window.location.hash.slice(1) || 'dashboard'
  const [view, ...rest] = hash.split('/')
  const param = rest.join('/')
  updateNav(view)
  const mc = document.getElementById('main-content')
  try {
    await ensureCatalogImages()
    if (view==='dashboard') await renderDashboard(mc)
    else if (view==='pullbacks') await renderPullbacks(mc)
    else if (view==='inventory') await renderCatalog(mc)
    else if (view==='invlog')    await renderInventoryLog(mc)
    else if (view==='scammed')   await renderScammed(mc)
    else if (view==='victims')   await renderVictims(mc)
    else if (view==='holders')   await renderHolders(mc)
    else if (view==='events')    await renderEvents(mc)
    else if (view==='settings')  await renderSettings(mc)
    else if (view==='asset')     await renderAsset(mc, param)
    else await renderDashboard(mc)
  } catch(e) {
    mc.innerHTML = `<div class="error-msg">⚠ ${h(e.message)}</div>`
  }
  mc.classList.remove('content-fade')
  void mc.offsetWidth
  mc.classList.add('content-fade')
}

/* — Modal ————————————————————————————————— */
function openModal(title, bodyHtml, buttons, wide) {
  document.getElementById('modal-title').textContent = title
  document.getElementById('modal-body').innerHTML = bodyHtml
  const footer = document.getElementById('modal-footer')
  footer.innerHTML = ''
  if (buttons) buttons.forEach(b => {
    const el = document.createElement('button')
    el.className = 'btn ' + (b.cls||'btn-outline')
    el.textContent = b.label
    el.onclick = b.fn
    footer.appendChild(el)
  })
  const ov = document.getElementById('modal-overlay')
  ov.classList.toggle('modal-wide', !!wide)
  ov.classList.add('open')
}

function closeModal() {
  document.getElementById('modal-overlay').classList.remove('open')
}

function modalError(msg) {
  let el = document.getElementById('_merr')
  if (!el) { el = document.createElement('div'); el.id='_merr'; el.className='modal-error'; document.getElementById('modal-body').appendChild(el) }
  el.textContent = msg
}

function setBtn(idx, label, disabled) {
  const btns = document.getElementById('modal-footer').querySelectorAll('button')
  if (btns[idx]) { btns[idx].textContent = label; btns[idx].disabled = disabled }
}

/* — Event Delegation ——————————————————————————— */
function setupEvents() {
  document.getElementById('sb-nav').addEventListener('click', e => {
    const btn = e.target.closest('[data-route]')
    if (btn) nav(btn.dataset.route)
  })

  let modalDownOnOverlay = false
  document.getElementById('modal-overlay').addEventListener('mousedown', e => {
    modalDownOnOverlay = (e.target === document.getElementById('modal-overlay'))
  })
  document.getElementById('modal-overlay').addEventListener('click', e => {
    if (modalDownOnOverlay && e.target === document.getElementById('modal-overlay')) closeModal()
  })
  document.getElementById('modal-close-btn').addEventListener('click', closeModal)

  document.getElementById('main-content').addEventListener('click', handleClick)
  document.getElementById('modal-body').addEventListener('click', handleClick)
  document.getElementById('tutorial-overlay').addEventListener('click', handleClick)

  document.addEventListener('click', e => {
    if (_quickStatusOpenId == null) return
    if (e.target.closest('[data-action="quick-status-toggle"],[data-action="quick-status-set"]')) return
    _quickStatusOpenId = null
    document.querySelectorAll('[id^="qs-dd-"]').forEach(dd => dd.style.display = 'none')
  })

  document.getElementById('main-content').addEventListener('input', handleInput)

  document.getElementById('main-content').addEventListener('change', handleChange)
  document.getElementById('modal-body').addEventListener('input', handleInput)
  document.getElementById('modal-body').addEventListener('change', handleChange)

  const AC_FIELDS = { 'si-account': ['si-account-dd', pickSiAccount], 'm-holder': ['m-holder-dropdown', pickPullbackHolder] }
  document.getElementById('modal-body').addEventListener('keydown', e => {
    const field = AC_FIELDS[e.target.id]; if (!field) return
    if (e.key !== 'Tab' && e.key !== 'Enter') return
    const [ddId, pick] = field
    const dd = document.getElementById(ddId)
    const first = dd && dd.style.display !== 'none' && dd.querySelector('.ac-item')
    if (!first) return
    e.preventDefault()
    pick(first.dataset.name)
  })

  document.getElementById('modal-body').addEventListener('focusin', e => {
    if (e.target.id === 'm-item' && window._pullbackHolderAssets) renderPullbackItemDropdown()
  })
}

function pickSiAccount(name) {
  const inp = document.getElementById('si-account'); if (inp) inp.value = name
  loadScamImportAssets(name)
}

function fetchPullbackHolderAssets(holder) {
  sbGet(`/ss_items?select=id,item_name,current_holder&current_status=eq.active&is_duped=eq.false&current_holder=ilike.${encodeURIComponent(holder)}&order=item_name`)
    .then(rows=>{window._pullbackHolderAssets=rows||[]; renderPullbackItemDropdown()})
    .catch(()=>{window._pullbackHolderAssets=[]})
}

function renderPullbackItemDropdown() {
  const dd=document.getElementById('m-item-dropdown'); if(!dd) return
  const assets=window._pullbackHolderAssets||[]
  if(!assets.length){
    dd.innerHTML=`<div style="padding:8px 12px;font-size:12px;color:var(--muted)">This account has nothing In Inventory yet — add it first via New Item.</div>`
    dd.style.display='block'; return
  }
  dd.innerHTML=assets.map(a=>`<div class="ac-item" data-action="pick-pullback-item" data-id="${h(a.id)}" data-name="${h(a.item_name)}">${itemThumb(a.item_name)}<span>${h(a.item_name)}</span></div>`).join('')
  dd.style.display='block'
}

function pickPullbackHolder(name) {
  const inp = document.getElementById('m-holder'); if (inp) inp.value = name
  const dd = document.getElementById('m-holder-dropdown'); if (dd) dd.style.display = 'none'
  window._pullbackSelectedAssetId = null
  const itemInp = document.getElementById('m-item'); if (itemInp) itemInp.value = ''
  fetchPullbackHolderAssets(name)
}

function handleClick(e) {
  const el = e.target.closest('[data-nav],[data-action]')
  if (!el) return

  if (el.dataset.nav) { nav(el.dataset.nav); return }

  const { action, id, key, val, status, idx } = el.dataset

  switch(action) {
    case 'refresh':           route(); break
    case 'new-asset':         openNewAssetModal(); break
    case 'clear-db':          openClearDbModal(); break
    case 'ban-holder':        openBanHolderModal(el.dataset.holder); break
    case 'unban-holder':      openUnbanHolderModal(el.dataset.holder); break
    case 'rename-holder':     openRenameHolderModal(el.dataset.holder); break
    case 'seed-ss-items':     openSeedSSItemsModal(); break
    case 'change-holder':     openChangeHolderModal(id); break
    case 'scam':              openScamModal(id); break
    case 'pullback':          openPullbackModal(id); break
    case 'lost':              openLostModal(id); break
    case 'restore':           openRestoreModal(id); break
    case 'edit-event':        { const d=window._evData&&window._evData[id]||{}; openEditEventModal(id,d); break }
    case 'delete-event':      openDeleteEventModal(id); break
    case 'filter-events':     { _evFilters={asset:'',trade:'',pb:'',holder:'',victim:'',type:'ALL'}; _evFilters[key]=val; _evTypeGroupOpen=null; closeModal(); nav('events'); break }
    case 'ev-type':           { _evFilters.type=el.dataset.evType; _evTypeGroupOpen=null; route(); break }
    case 'ev-type-group': {
      const i = parseInt(el.dataset.group)
      const wasOpen = _evTypeGroupOpen === i
      _evTypeGroupOpen = wasOpen ? null : i
      document.querySelectorAll('[id^="ev-type-dd-"]').forEach(dd => dd.style.display = 'none')
      document.querySelectorAll('[data-action="ev-type-group"]').forEach(b => b.classList.remove('active'))
      if (!wasOpen) {
        const dd = document.getElementById(`ev-type-dd-${i}`)
        if (dd) dd.style.display = 'block'
        el.classList.add('active')
      }
      break
    }
    case 'clear-ev-filters':  { _evFilters={asset:'',trade:'',pb:'',holder:'',victim:'',type:'ALL'}; _evTypeGroupOpen=null; route(); break }
    case 'apply-ev-filters':  route(); break
    case 'inv-status':        { _invStatus=status; renderPullbacks(document.getElementById('main-content')); break }
    case 'quick-status-toggle': {
      const wasOpen = _quickStatusOpenId === id
      _quickStatusOpenId = wasOpen ? null : id
      document.querySelectorAll('[id^="qs-dd-"]').forEach(dd => dd.style.display = 'none')
      if (!wasOpen) { const dd = document.getElementById(`qs-dd-${id}`); if (dd) dd.style.display = 'block' }
      break
    }
    case 'quick-status-set': {
      _quickStatusOpenId = null
      const newStatus = el.dataset.newStatus
      const holder = el.dataset.holder
      ;(async () => {
        try { await doEditAsset(id, holder, newStatus, undefined, undefined, undefined, undefined); route() }
        catch(err) { alert(err.message) }
      })()
      break
    }
    case 'log-status':        { _logStatus=status; renderInventoryLog(document.getElementById('main-content')); break }
    case 'cat-filter':        { _catFilter=el.dataset.filter; renderCatalog(document.getElementById('main-content')); break }
    case 'holder-filter':     { _holderFilter=el.dataset.filter; renderHolders(document.getElementById('main-content')); break }
    case 'scam-filter':       { _scamFilter=el.dataset.filter; renderScammed(document.getElementById('main-content')); break }
    case 'goto-pullbacks':    { _invStatus=el.dataset.status||'ALL'; closeModal(); nav('pullbacks'); break }
    case 'goto-inventory':    { _catFilter=el.dataset.filter||'ALL'; closeModal(); nav('inventory'); break }
    case 'dash-toggle-metric':{ const k=el.dataset.key; _dashVisibleMetrics.has(k)?_dashVisibleMetrics.delete(k):_dashVisibleMetrics.add(k); renderDashboard(document.getElementById('main-content')); break }
    case 'dash-granularity': { _dashGranularity=el.dataset.val; renderDashboard(document.getElementById('main-content')); break }
    case 'close-modal':       closeModal(); break
    case 'edit-asset':        openEditAssetModal(id, el.dataset.holder, el.dataset.status, el.dataset.duped==='1', el.dataset.itemName, el.dataset.context||'pullback', el.dataset.itemHolder, el.dataset.notes); break
    case 'mark-trade-pulled': openTradePulledModal(id, el.dataset.holder, el.dataset.itemName); break
    case 'open-trade-detail': openTradeDetailModal(id); break
    case 'show-trade-item-info': { window._tradeDetailActiveItem = el.dataset.name; renderTradeDetailModal(window._tradeDetailEventId); break }
    case 'delete-asset':      openDeleteAssetModal(id); break
    case 'open-cat-item':     openCatItemModal(el.dataset.name); break
    case 'open-holder-items': openHolderItemsModal(el.dataset.holder); break
    case 'show-holder-item':  { window._holderItemsActive = el.dataset.id; renderHolderItemsModal(); break }
    case 'open-bc-modal':     openBcModal(); break
    case 'open-tutorials':    openTutorialPicker(); break
    case 'start-tutorial':    startTutorial(el.dataset.tut); break
    case 'tutorial-next':     tutorialNext(); break
    case 'tutorial-prev':     tutorialPrev(); break
    case 'tutorial-close':    endTutorial(); break
    case 'open-import-item':  openImportItemModal(); break
    case 'stub-import-db':    modalError('Not built yet — coming soon.'); break
    case 'toggle-import-duped': { const cb=el.querySelector('.check-box'); if(cb) cb.classList.toggle('checked'); el.classList.toggle('selected'); break }
    case 'open-scam-import':  openScamImportModal(); break
    case 'pick-si-account':   pickSiAccount(el.dataset.name); break
    case 'pick-pullback-holder': pickPullbackHolder(el.dataset.name); break
    case 'open-scam-slot-picker':  { window._scamImportPicker={side:el.dataset.side,slot:parseInt(el.dataset.slot)}; window._scamImportPickerSearch=''; renderScamImportModal(); break }
    case 'close-scam-slot-picker': { window._scamImportPicker=null; renderScamImportModal(); break }
    case 'pick-scam-slot-item':    {
      const side = el.dataset.side
      const arr = side==='given' ? window._scamImportGiven : window._scamImportReceived
      const name = el.dataset.name, id = el.dataset.id
      const existing = arr.find(s=>s && s.name===name)
      if (existing) { existing.qty++; if (id!==undefined) existing.ids.push(id) }
      else { arr[parseInt(el.dataset.slot)] = {name, qty:1, ids: id!==undefined?[id]:[]} }
      const nextEmpty = arr.findIndex(s=>!s)
      window._scamImportPicker = nextEmpty!==-1 ? {side, slot:nextEmpty} : null
      renderScamImportModal(); break
    }
    case 'remove-scam-slot-item':  {
      const arr = el.dataset.side==='given' ? window._scamImportGiven : window._scamImportReceived
      arr[parseInt(el.dataset.slot)] = null
      renderScamImportModal(); break
    }
    case 'inc-scam-slot-qty': {
      const side = el.dataset.side, i = parseInt(el.dataset.slot)
      const arr = side==='given' ? window._scamImportGiven : window._scamImportReceived
      const slot = arr[i]; if (!slot) break
      const isAssetBased = side==='given' && window._scamModalMode==='create'
      if (isAssetBased) {
        const usedIds = new Set(arr.flatMap(s=>s?s.ids:[]))
        const candidate = (window._scamImportAssets||[]).find(a=>a.item_name===slot.name && !usedIds.has(a.id))
        if (!candidate) { modalError(`No more "${slot.name}" available in this account's inventory.`); break }
        slot.qty++; slot.ids.push(candidate.id)
      } else {
        slot.qty++
      }
      renderScamImportModal(); break
    }
    case 'dec-scam-slot-qty': {
      const side = el.dataset.side, i = parseInt(el.dataset.slot)
      const arr = side==='given' ? window._scamImportGiven : window._scamImportReceived
      const slot = arr[i]; if (!slot) break
      slot.qty--
      if (slot.qty<=0) arr[i]=null
      else if (slot.ids.length) slot.ids.pop()
      renderScamImportModal(); break
    }
    case 'bulk-import-catalog': importBulkCatalog(); break
    case 'save-catimg': {
      const row=el.closest('.catimg-row')
      const url=row.querySelector('.catimg-url').value.trim()
      const valRaw=row.querySelector('.catimg-value').value
      saveCatalogImage(el.dataset.name, url, valRaw!==''?Number(valRaw):null, el)
      break
    }
    case 'pick-item': {
      const inp=document.getElementById('m-item'); if(inp) inp.value=el.dataset.name
      const dd=document.getElementById('m-item-dropdown'); if(dd) dd.style.display='none'
      break
    }
    case 'pick-pullback-item': {
      const inp=document.getElementById('m-item'); if(inp) inp.value=el.dataset.name
      const dd=document.getElementById('m-item-dropdown'); if(dd) dd.style.display='none'
      window._pullbackSelectedAssetId = el.dataset.id
      break
    }
    case 'pick-import-item': {
      const inp=document.getElementById('m-import-item'); if(inp) inp.value=el.dataset.name
      const dd=document.getElementById('m-import-item-dropdown'); if(dd) dd.style.display='none'
      break
    }
    case 'pick-scam-item': {
      if(!window._scamItems) window._scamItems=[]
      window._scamItems.push(el.dataset.name)
      const inp=document.getElementById('m-scam-item-input'); if(inp) inp.value=''
      const dd=document.getElementById('m-scam-item-dd'); if(dd) dd.style.display='none'
      refreshScamItems(); break
    }
    case 'remove-scam-item': {
      if(window._scamItems) window._scamItems.splice(parseInt(el.dataset.idx),1)
      refreshScamItems(); break
    }
    case 'pick-scam-recv-item': {
      if(!window._scamRecvItems) window._scamRecvItems=[]
      window._scamRecvItems.push(el.dataset.name)
      const inp=document.getElementById('m-scam-recv-input'); if(inp) inp.value=''
      const dd=document.getElementById('m-scam-recv-dd'); if(dd) dd.style.display='none'
      refreshScamRecvItems(); break
    }
    case 'remove-scam-recv-item': {
      if(window._scamRecvItems) window._scamRecvItems.splice(parseInt(el.dataset.idx),1)
      refreshScamRecvItems(); break
    }
  }
}

const _searchDebounceTimers = {}
function liveSearch(key, renderFn, mc, value) {
  clearTimeout(_searchDebounceTimers[key])
  _searchDebounceTimers[key] = setTimeout(() => {
    renderFn(mc, value).then(() => {
      const el = document.querySelector(`[data-input-action="${key}"]`)
      if (el) { el.focus(); const v=el.value; el.setSelectionRange(v.length, v.length) }
    })
  }, 220)
}

function handleInput(e) {
  const { inputAction } = e.target.dataset
  const mc = document.getElementById('main-content')
  switch(inputAction) {
    case 'inv-search':       liveSearch('inv-search', renderPullbacks, mc, e.target.value); break
    case 'log-search':       liveSearch('log-search', renderInventoryLog, mc, e.target.value); break
    case 'cat-search':       liveSearch('cat-search', renderCatalog, mc, e.target.value); break
    case 'scam-search':      liveSearch('scam-search', renderScammed, mc, e.target.value); break
    case 'victim-search':    liveSearch('victim-search', renderVictims, mc, e.target.value); break
    case 'holder-search':    liveSearch('holder-search', renderHolders, mc, e.target.value); break
    case 'settings-img-search': { _settingsImgSearch=e.target.value; refreshCatimgList(); break }
    case 'scam-slot-search':   { window._scamImportPickerSearch=e.target.value; renderScamImportModal(); const inp=document.getElementById('modal-body').querySelector('[data-input-action="scam-slot-search"]'); if(inp){inp.focus();inp.selectionStart=inp.selectionEnd=inp.value.length} break }
    case 'si-account-ac': {
      const val=e.target.value.trim(), dd=document.getElementById('si-account-dd')
      if(!dd) break
      const holders=(window._scamImportHolders||[])
      const exact=holders.find(n=>n.toLowerCase()===val.toLowerCase())
      if(exact && exact!==window._scamImportAccount){ dd.style.display='none'; loadScamImportAssets(exact); break }
      if(val.length<2){dd.style.display='none';break}
      const vl3=val.toLowerCase()
      const matches=[...holders.filter(n=>n.toLowerCase().startsWith(vl3)),...holders.filter(n=>n.toLowerCase().includes(vl3)&&!n.toLowerCase().startsWith(vl3))].slice(0,10)
      if(!matches.length){dd.style.display='none';break}
      dd.innerHTML=matches.map(n=>`<div class="ac-item" data-action="pick-si-account" data-name="${h(n)}">${h(n)}</div>`).join('')
      dd.style.display='block'; break
    }
    case 'scam-item-ac':      itemAutocomplete(e.target, 'm-scam-item-dd', 'pick-scam-item'); break
    case 'scam-recv-item-ac': itemAutocomplete(e.target, 'm-scam-recv-dd', 'pick-scam-recv-item'); break
    case 'pullback-holder-ac': {
      const holder=e.target.value.trim(), dd=document.getElementById('m-holder-dropdown')
      window._pullbackSelectedAssetId = null
      const itemInp=document.getElementById('m-item'); if(itemInp) itemInp.value=''
      if(holder.length<2){window._pullbackHolderAssets=[]; if(dd) dd.style.display='none'; break}
      fetchPullbackHolderAssets(holder)
      if(dd){
        const known=window._pullbackHolders||[]
        const exact=known.find(n=>n.toLowerCase()===holder.toLowerCase())
        const vl=holder.toLowerCase()
        const matches=exact?[]:[...known.filter(n=>n.toLowerCase().startsWith(vl)),...known.filter(n=>n.toLowerCase().includes(vl)&&!n.toLowerCase().startsWith(vl))].slice(0,10)
        if(!matches.length){dd.style.display='none'}
        else{dd.innerHTML=matches.map(n=>`<div class="ac-item" data-action="pick-pullback-holder" data-name="${h(n)}">${h(n)}</div>`).join(''); dd.style.display='block'}
      }
      break
    }
    case 'pullback-item-ac': {
      window._pullbackSelectedAssetId = null
      const val=e.target.value.trim()
      if(val.length<1){renderPullbackItemDropdown();break}
      const dd=document.getElementById('m-item-dropdown'); if(!dd) break
      const assets=window._pullbackHolderAssets||[]
      const vl=val.toLowerCase()
      const matches=assets.filter(a=>a.item_name.toLowerCase().includes(vl))
      if(!matches.length){
        dd.innerHTML=`<div style="padding:8px 12px;font-size:12px;color:var(--muted)">${assets.length?'No matching item in this account\'s inventory.':'This account has nothing In Inventory yet — add it first via New Item.'}</div>`
        dd.style.display='block'; break
      }
      dd.innerHTML=matches.map(a=>`<div class="ac-item" data-action="pick-pullback-item" data-id="${h(a.id)}" data-name="${h(a.item_name)}">${itemThumb(a.item_name)}<span>${h(a.item_name)}</span></div>`).join('')
      dd.style.display='block'; break
    }
    case 'item-ac':            itemAutocomplete(e.target, 'm-item-dropdown', 'pick-item'); break
    case 'import-item-ac':     itemAutocomplete(e.target, 'm-import-item-dropdown', 'pick-import-item'); break
    case 'ev-asset':         _evFilters.asset=e.target.value; break
    case 'ev-holder':        _evFilters.holder=e.target.value; break
    case 'ev-victim':        _evFilters.victim=e.target.value; break
  }
}

function itemAutocomplete(inputEl, ddId, pickAction) {
  const dd = document.getElementById(ddId); if (!dd) return
  const val = inputEl.value.trim()
  if (val.length<2) { dd.style.display='none'; return }
  const vl = val.toLowerCase(), all = SS_ITEM_NAMES.filter(n=>n.toLowerCase().includes(vl))
  const matches = [...all.filter(n=>n.toLowerCase().startsWith(vl)), ...all.filter(n=>!n.toLowerCase().startsWith(vl))].slice(0,10)
  if (!matches.length) { dd.style.display='none'; return }
  dd.innerHTML = matches.map(n=>`<div class="ac-item" data-action="${pickAction}" data-name="${h(n)}">${itemThumb(n)}<span>${h(n)}</span></div>`).join('')
  dd.style.display='block'
}

function handleChange(e) {
  if (e.target.id === 'si-scam-type') { renderScamImportModal(); return }
  if (e.target.id === 'm-status') {
    const wrap = document.getElementById('m-edit-stays-wrap')
    if (wrap) wrap.style.display = e.target.value === 'pullbacked' ? '' : 'none'
    return
  }
  if (e.target.id === 'm-import-acquired') {
    const wrap = document.getElementById('m-import-hacked-from-wrap')
    if (wrap) wrap.style.display = e.target.value === 'hacked' ? '' : 'none'
    return
  }
  if (e.target.id === 'bulk-import-file') {
    const files = [...e.target.files]; if (!files.length) return
    Promise.all(files.map(f => f.text())).then(texts => {
      let combined = [], failed = 0
      for (const t of texts) {
        try { const parsed = JSON.parse(t); if (Array.isArray(parsed)) combined = combined.concat(parsed); else failed++ }
        catch(err) { failed++ }
      }
      const ta = document.getElementById('bulk-import-json'); if (ta) ta.value = JSON.stringify(combined)
      const statusEl = document.getElementById('bulk-import-status')
      if (statusEl) { statusEl.style.color='var(--muted)'; statusEl.textContent = `Loaded ${files.length} file(s), ${combined.length} items combined${failed?`, ${failed} file(s) failed to parse`:''}. Click Import to save.` }
    })
  }
}

/* — Dashboard ——————————————————————————————— */
async function renderDashboard(mc) {
  const [items, scams, bcRaw, bannedRaw] = await Promise.all([
    sbGet('/ss_items?select=id,item_name,current_status,current_holder,is_duped,item_holder'),
    sbGet('/ss_item_events?select=scammed_user,item_id&event_type=eq.marketplace_sale'),
    sbGet('/bc_balances?select=holder,amount').catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null)
  ])

  const ai=items||[], sc=scams||[]
  const bannedSet = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))
  const bcInInventory = (bcRaw||[]).filter(r=>!isBanned(bannedSet,r.holder)).reduce((s,r)=>s+(r.amount||0),0)
  const inInvItems = ai.filter(a=>a.current_status==='active'&&!a.is_duped)
  const isPullbackClaim = a => !a.is_duped && a.item_holder
  const rfpItems = ai.filter(a=>a.current_status==='traded'&&isPullbackClaim(a))
  const pulledBackCount = ai.filter(a=>a.current_status==='pullbacked'&&isPullbackClaim(a)).length
  const lostCount = ai.filter(a=>a.current_status==='lost'&&isPullbackClaim(a)).length
  const uniqueVictims = new Set(sc.map(e=>e.scammed_user).filter(Boolean).map(n=>n.toLowerCase())).size
  const activeHolders = new Set(ai.filter(a=>a.current_status!=='lost').map(a=>a.current_holder).filter(Boolean).map(n=>n.toLowerCase())).size
  const values = window._catalogValues||{}
  const totalWorth = inInvItems.reduce((s,a)=>s+(values[a.item_name]||0),0) + rfpItems.reduce((s,a)=>s+(values[a.item_name]||0),0) + bcInInventory
  const stats=[
    {label:'Total Inventory Worth (BC)', val:fmtWorthK(totalWorth), title:totalWorth.toLocaleString()+' BC', color:'var(--yellow)', nav:'inventory'},
    {label:'Ready for Pullback', val:rfpItems.length,      color:'var(--orange)', action:'goto-pullbacks', status:'traded'},
    {label:'In Inventory',       val:inInvItems.length,    color:'var(--green)',  action:'goto-inventory', filter:'IN_INV'},
    {label:'Pulled Back',        val:pulledBackCount,      color:'var(--red)',    action:'goto-pullbacks', status:'pullbacked'},
    {label:'Lost',               val:lostCount,            color:'var(--zinc)',   action:'goto-pullbacks', status:'lost'},
    {label:'Unique Victims',val:uniqueVictims,   color:'var(--pink)',   nav:'victims'},
    {label:'Active Holders',val:activeHolders, color:'var(--primary)', nav:'holders'}
  ]

  await backfillDashboardHistory()
  await ensureTodaySnapshot({
    ready_for_pullback: rfpItems.length,
    in_inventory: inInvItems.length,
    pulled_back: pulledBackCount,
    lost: lostCount,
    inventory_worth: totalWorth,
    unique_victims: uniqueVictims,
    active_holders: activeHolders
  })
  const history = await fetchDashboardHistory()

  mc.innerHTML = `
    <div class="page-hdr">
      <div><div class="page-title">Dashboard</div><div class="page-sub">SS item case management</div></div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-outline" data-action="open-tutorials">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
          Tutorials
        </button>
        <button class="btn btn-outline" data-action="refresh">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M23 4v6h-6"/><path d="M1 20v-6h6"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>
          Refresh
        </button>
      </div>
    </div>
    <div class="dash-stats-row">
      ${stats.map(statCard).join('')}
    </div>
    ${renderDashboardChart(history)}`
  wireDashboardChart()
}

function statCard(s) {
  return `<button class="dash-stat" style="--stat-color:${s.color}" ${s.title?`title="${h(s.title)}"`:''} ${s.nav?`data-nav="${s.nav}"`:`data-action="${s.action}" ${s.status?`data-status="${s.status}"`:''} ${s.filter?`data-filter="${s.filter}"`:''}`}>
    <div class="dash-stat-val">${s.val}</div>
    <div class="dash-stat-lbl">${s.label}</div>
  </button>`
}

/* — Dashboard trend chart —————————————————————————— */
const CHART_METRICS = [
  {key:'inventory_worth',    label:'Total Inventory Worth', color:'var(--yellow)'},
  {key:'ready_for_pullback', label:'Ready for Pullback',    color:'var(--orange)'},
  {key:'in_inventory',       label:'In Inventory',          color:'var(--green)'},
  {key:'pulled_back',        label:'Pulled Back',           color:'var(--red)'},
  {key:'lost',                label:'Lost',                  color:'var(--zinc)'},
  {key:'unique_victims',     label:'Unique Victims',        color:'var(--pink)'},
  {key:'active_holders',     label:'Active Holders',        color:'var(--primary)'}
]
let _dashGranularity = 'all'
let _dashVisibleMetrics = new Set(['inventory_worth'])
function metricValue(p, key) {
  const v = p[key]||0
  return key==='inventory_worth' ? Math.round(v/1000) : v
}

async function ensureTodaySnapshot(vals) {
  const today = new Date().toISOString().slice(0,10)
  try { await sbUpsert('/dashboard_snapshots?on_conflict=date', { date: today, ...vals }) }
  catch(e) { /* table not created yet — silently skip, chart just stays empty */ }
}

async function fetchDashboardHistory() {
  try { return await sbGet('/dashboard_snapshots?select=*&order=date.asc&limit=1000') || [] }
  catch(e) { return [] }
}

async function invalidateDashboardHistory() {
  await sbDel('/dashboard_snapshots?date=not.is.null').catch(()=>{})
}

async function backfillDashboardHistory() {
  const today = new Date().toISOString().slice(0,10)
  const existing = await sbGet('/dashboard_snapshots?select=date&order=date.asc&limit=1').catch(()=>null)
  if (existing === null) return
  if (existing.length && existing[0].date < today) return

  const [items, events, scamEvts] = await Promise.all([
    sbGet('/ss_items?select=id,item_name,current_holder,is_duped,created_at').catch(()=>null),
    sbGet('/ss_item_events?select=item_id,event_type,reason,timestamp&order=timestamp.asc').catch(()=>null),
    sbGet('/ss_item_events?select=scammed_user,timestamp&event_type=eq.marketplace_sale&scammed_user=not.is.null&order=timestamp.asc').catch(()=>null)
  ])
  if (!items || !items.length) return

  const evByItem = new Map()
  for (const e of (events||[])) { if (!evByItem.has(e.item_id)) evByItem.set(e.item_id,[]); evByItem.get(e.item_id).push(e) }

  const timelines = new Map()
  const allDays = new Set()
  for (const a of items) {
    const evs = evByItem.get(a.id) || []
    let status = a.is_duped ? 'active' : (evs[0]?.event_type==='dupe' ? 'traded' : 'active')
    const created = (a.created_at || evs[0]?.timestamp || today).slice(0,10)
    const timeline = [{date:created, status}]
    allDays.add(created)
    for (const e of evs) {
      let next = status
      if (e.event_type==='marketplace_sale') next='traded'
      else if (e.event_type==='pullback') next='pullbacked'
      else if (e.event_type==='manual_update') {
        if (e.reason==='LOST') next='lost'
        else if (e.reason==='RESTORED') next='active'
      }
      if (next!==status) { status=next; const d=e.timestamp.slice(0,10); timeline.push({date:d,status}); allDays.add(d) }
    }
    timelines.set(a.id, timeline)
  }
  for (const e of (scamEvts||[])) allDays.add(e.timestamp.slice(0,10))

  const statusAt = (timeline, day) => {
    let s = timeline[0].status
    for (const t of timeline) { if (t.date<=day) s=t.status; else break }
    return s
  }

  const values = window._catalogValues||{}
  const days = [...allDays].filter(d=>d<today).sort()
  const rows = []
  for (const day of days) {
    let rfp=0, inv=0, pb=0, lost=0, worth=0
    const holderSet = new Set()
    for (const a of items) {
      const tl = timelines.get(a.id)
      if (tl[0].date > day) continue
      const s = statusAt(tl, day)
      if (s==='lost') { lost++; continue }
      if (a.current_holder) holderSet.add(a.current_holder.toLowerCase())
      if (s==='pullbacked') pb++
      if (s==='active' && !a.is_duped) { inv++; worth += values[a.item_name]||0 }
      else if (s==='traded' && !a.is_duped) { rfp++; worth += values[a.item_name]||0 }
    }
    const victims = new Set((scamEvts||[]).filter(e=>e.timestamp.slice(0,10)<=day).map(e=>e.scammed_user).filter(Boolean).map(n=>n.toLowerCase())).size
    rows.push({date:day, ready_for_pullback:rfp, in_inventory:inv, pulled_back:pb, lost, inventory_worth:worth, unique_victims:victims, active_holders:holderSet.size})
  }
  if (rows.length) await sbUpsert('/dashboard_snapshots?on_conflict=date', rows).catch(()=>{})
}

const GRANULARITY_WINDOW_DAYS = { day: 30, week: 182, month: 730, all: Infinity }

function bucketKey(dateStr, granularity) {
  if (granularity==='month') return dateStr.slice(0,7)
  if (granularity==='week') {
    const d = new Date(dateStr+'T00:00:00Z')
    const dow = (d.getUTCDay()+6)%7
    d.setUTCDate(d.getUTCDate()-dow)
    return d.toISOString().slice(0,10)
  }
  return dateStr
}

function bucketTime(bucket, granularity) {
  if (granularity==='month') { const [y,m] = bucket.split('-'); return Date.UTC(y,m-1,1) }
  return new Date(bucket+'T00:00:00Z').getTime()
}

function fmtBucketLabel(bucket, granularity) {
  if (granularity==='month') {
    const [y,m] = bucket.split('-')
    return new Date(Date.UTC(y,m-1,1)).toLocaleDateString(undefined,{month:'short',year:'2-digit'})
  }
  return new Date(bucket+'T00:00:00Z').toLocaleDateString(undefined,{month:'short',day:'numeric'})
}

function aggregateHistory(rows, granularity) {
  const windowDays = GRANULARITY_WINDOW_DAYS[granularity] ?? Infinity
  let windowed = rows
  if (windowDays !== Infinity) {
    const cutoff = new Date(); cutoff.setUTCDate(cutoff.getUTCDate()-windowDays)
    const cutoffStr = cutoff.toISOString().slice(0,10)
    windowed = rows.filter(r => r.date >= cutoffStr)
  }
  const buckets = new Map()
  for (const r of windowed) buckets.set(bucketKey(r.date, granularity), r)
  return [...buckets.entries()].map(([k,r])=>({...r,_bucket:k})).sort((a,b)=>a._bucket<b._bucket?-1:a._bucket>b._bucket?1:0)
}

function renderDashboardChart(history) {
  const points = aggregateHistory(history, _dashGranularity)
  const visible = CHART_METRICS.filter(m=>_dashVisibleMetrics.has(m.key))
  const W=760, H=260, padL=44, padR=16, padT=16, padB=26
  const plotW=W-padL-padR, plotH=H-padT-padB
  const n = points.length

  let svgBody, tableRows, chartTimes = []
  if (!n) {
    svgBody = `<text x="${W/2}" y="${H/2}" text-anchor="middle" fill="var(--muted)" font-size="12">No history yet — snapshots start accumulating from today.</text>`
    tableRows = ''
  } else {
    const times = points.map(p=>bucketTime(p._bucket,_dashGranularity))
    chartTimes = times
    const t0 = times[0], t1 = times[n-1]
    const xFor = i => (t1===t0) ? padL+plotW/2 : padL + plotW*(times[i]-t0)/(t1-t0)
    let rawMaxY = 1
    for (const p of points) for (const m of visible) rawMaxY = Math.max(rawMaxY, metricValue(p,m.key))
    const GRID_STEPS = [1,2,5,10,25,50,100,250,500,1000,2500,5000,10000,25000,50000,100000,250000,500000,1000000]
    const roughMax = rawMaxY*1.15 || 1
    const GRID_STEP = GRID_STEPS.find(s => roughMax/s <= 8) || GRID_STEPS[GRID_STEPS.length-1]
    const maxY = Math.ceil(roughMax/GRID_STEP)*GRID_STEP || GRID_STEP
    const yFor = v => padT + plotH - plotH*(v/maxY)

    let grid = ''
    for (let v=0; v<=maxY; v+=GRID_STEP) {
      const y = yFor(v)
      grid += `<line x1="${padL}" y1="${y.toFixed(1)}" x2="${W-padR}" y2="${y.toFixed(1)}" stroke="var(--border)" stroke-width="1"/>`
      grid += `<text x="${padL-6}" y="${(y+3).toFixed(1)}" text-anchor="end" font-size="10" fill="var(--muted)">${v.toLocaleString()}</text>`
    }

    let xticks = ''
    const DAY_MS = 86400000
    const spanDays = Math.max(1, (t1-t0)/DAY_MS)
    const DAY_STEPS = [1,2,3,7,14,21,30,60,90,180,365,730]
    const dayStep = DAY_STEPS.find(s => spanDays/s <= 8) || DAY_STEPS[DAY_STEPS.length-1]
    const tickStepMs = dayStep*DAY_MS
    let prevMonth = null
    for (let time=t0; time<=t1; time+=tickStepMs) {
      const frac = t1===t0 ? 0 : (time-t0)/(t1-t0)
      const x = padL + plotW*frac
      const d = new Date(time)
      const month = _dashGranularity==='month' ? d.getUTCFullYear()*12+d.getUTCMonth() : d.getUTCMonth()
      const label = month!==prevMonth
        ? d.toLocaleDateString(undefined, _dashGranularity==='month' ? {month:'short',year:'2-digit'} : {month:'short',day:'numeric'})
        : (_dashGranularity==='month' ? d.toLocaleDateString(undefined,{month:'short'}) : String(d.getUTCDate()))
      prevMonth = month
      xticks += `<line x1="${x.toFixed(1)}" y1="${H-padB}" x2="${x.toFixed(1)}" y2="${H-padB+4}" stroke="var(--border)" stroke-width="1"/>`
      xticks += `<text x="${x.toFixed(1)}" y="${H-8}" text-anchor="middle" font-size="10" fill="var(--muted)">${h(label)}</text>`
    }

    const lines = visible.map(m=>{
      let d = `M${xFor(0).toFixed(1)},${yFor(metricValue(points[0],m.key)).toFixed(1)}`
      for (let i=1;i<n;i++) {
        const prevY = yFor(metricValue(points[i-1],m.key)), x = xFor(i), y = yFor(metricValue(points[i],m.key))
        d += ` L${x.toFixed(1)},${prevY.toFixed(1)} L${x.toFixed(1)},${y.toFixed(1)}`
      }
      const lastX=xFor(n-1), lastY=yFor(metricValue(points[n-1],m.key))
      return `<path d="${d}" fill="none" stroke="${m.color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${lastX.toFixed(1)}" cy="${lastY.toFixed(1)}" r="3" fill="${m.color}"/>`
    }).join('')

    svgBody = `${grid}${lines}${xticks}
      <line id="dash-chart-crosshair" x1="0" y1="${padT}" x2="0" y2="${H-padB}" stroke="var(--muted)" stroke-width="1" opacity="0" pointer-events="none"/>
      <rect data-chart-hitrect data-padl="${padL}" data-plotw="${plotW}" data-n="${n}" x="${padL}" y="${padT}" width="${plotW}" height="${plotH}" fill="transparent"/>`

    tableRows = points.map(p=>`<tr><td>${h(fmtBucketLabel(p._bucket,_dashGranularity))}</td>${CHART_METRICS.map(m=>`<td style="text-align:right">${metricValue(p,m.key).toLocaleString()}</td>`).join('')}</tr>`).join('')
  }

  window._dashChartPoints = points
  window._dashChartVisible = visible
  window._dashChartTimes = chartTimes

  const legend = CHART_METRICS.map(m=>{
    const on = _dashVisibleMetrics.has(m.key)
    return `<button class="dash-chart-legend-item${on?' on':''}" data-action="dash-toggle-metric" data-key="${m.key}" style="--m-color:${m.color}"><span class="dash-chart-dot"></span>${h(m.label)}</button>`
  }).join('')
  const granLabels = {day:'Day',week:'Week',month:'Month',all:'All Time'}
  const granChips = ['day','week','month','all'].map(g=>`<button class="filter-chip${_dashGranularity===g?' active':''}" data-action="dash-granularity" data-val="${g}">${granLabels[g]}</button>`).join('')
  return `
    <div class="card" style="margin-top:16px">
      <div class="card-header">
        <span class="card-title">Trends</span>
        <div class="dash-chart-gran" style="display:flex;gap:6px">${granChips}</div>
      </div>
      <div class="card-body" style="padding:14px">
        <div class="dash-chart-legend" style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px">${legend}</div>
        <div style="position:relative">
          <svg id="dash-chart-svg" viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block">${svgBody}</svg>
          <div id="dash-chart-tooltip" class="dash-chart-tooltip" style="display:none"></div>
        </div>
        <details style="margin-top:10px"><summary style="cursor:pointer;font-size:11px;color:var(--muted)">View as table</summary>
          <div class="tbl-wrap" style="margin-top:8px"><table><thead><tr><th>Date</th>${CHART_METRICS.map(m=>`<th style="text-align:right">${h(m.label)}</th>`).join('')}</tr></thead><tbody>${tableRows||`<tr class="empty-row"><td colspan="8">No data yet.</td></tr>`}</tbody></table></div>
        </details>
      </div>
    </div>`
}

function wireDashboardChart() {
  const svg = document.getElementById('dash-chart-svg')
  const hit = svg && svg.querySelector('[data-chart-hitrect]')
  const tooltip = document.getElementById('dash-chart-tooltip')
  const crosshair = document.getElementById('dash-chart-crosshair')
  if (!svg || !hit || !tooltip) return
  const padL = parseFloat(hit.dataset.padl), plotW = parseFloat(hit.dataset.plotw), n = parseInt(hit.dataset.n)
  const points = window._dashChartPoints||[], visible = window._dashChartVisible||[]
  const times = window._dashChartTimes||[]
  if (!n || !visible.length) return
  const t0 = times[0], t1 = times[n-1]
  const xForTime = time => (t1===t0) ? padL+plotW/2 : padL + plotW*(time-t0)/(t1-t0)
  const vb = svg.viewBox.baseVal
  svg.addEventListener('mousemove', e => {
    const rect = svg.getBoundingClientRect()
    const svgX = (e.clientX-rect.left) * (vb.width/rect.width)
    const x = Math.min(padL+plotW, Math.max(padL, svgX))
    const targetTime = t0 + ((svgX-padL)/plotW)*(t1-t0)
    let i = 0, best = Infinity
    for (let k=0;k<n;k++) { const d=Math.abs(times[k]-targetTime); if (d<best) { best=d; i=k } }
    crosshair.setAttribute('x1', x); crosshair.setAttribute('x2', x); crosshair.setAttribute('opacity','1')
    const p = points[i]
    tooltip.style.display='block'
    tooltip.style.left = Math.min(90, Math.max(0, x/vb.width*100)) + '%'
    tooltip.innerHTML = `<div style="font-weight:700;margin-bottom:4px">${h(fmtBucketLabel(p._bucket,_dashGranularity))}</div>` +
      visible.map(m=>`<div style="display:flex;align-items:center;gap:5px;white-space:nowrap"><span style="width:8px;height:8px;border-radius:50%;background:${m.color};display:inline-block"></span>${h(m.label)}: <strong>${(p[m.key]||0).toLocaleString()}</strong></div>`).join('')
  })
  svg.addEventListener('mouseleave', () => { tooltip.style.display='none'; crosshair.setAttribute('opacity','0') })
}

/* — Pullbacks (raw asset list, per-row holder/status edit) —— */
let _invSearch='', _invStatus='ALL'

async function renderPullbacks(mc, search) {
  if (search !== undefined) _invSearch = search
  let q = '/ss_items?select=*&order=created_at.desc&limit=300'
  q += _invStatus && _invStatus !== 'ALL' ? `&current_status=eq.${_invStatus}` : '&current_status=in.(traded,pullbacked,lost)'
  if (_invSearch) { const s=encodeURIComponent(_invSearch); q+=`&or=(id.ilike.*${s}*,current_holder.ilike.*${s}*,item_name.ilike.*${s}*)` }
  const [itemsRaw, bannedRaw, statsRaw] = await Promise.all([
    sbGet(q).catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null),
    sbGet('/ss_items?select=current_status,is_duped,item_holder&current_status=in.(traded,pullbacked,lost)').catch(()=>null)
  ])
  const items = (itemsRaw || []).filter(a=>!a.is_duped && a.item_holder)
  const bannedSet = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))
  const statsAll = (statsRaw || []).filter(a=>!a.is_duped && a.item_holder)
  const pbStatPulled = statsAll.filter(a=>a.current_status==='pullbacked').length
  const pbStatReady = statsAll.filter(a=>a.current_status==='traded').length
  const pbStatTotal = pbStatPulled + pbStatReady

  const soldToMap = new Map()
  const idsWithItemHolder = items.filter(a=>a.item_holder).map(a=>a.id)
  if (idsWithItemHolder.length) {
    const soldEvts = await sbGet(`/ss_item_events?select=item_id,scammed_user&event_type=eq.marketplace_sale&item_id=in.(${idsWithItemHolder.join(',')})`).catch(()=>null)
    for (const e of (soldEvts||[])) if (e.scammed_user) soldToMap.set(e.item_id, e.scammed_user)
  }

  const statusOpts = ['ALL','traded','pullbacked','lost']
  const statusLabels = {ALL:'All',active:'In Inventory',traded:'Ready for Pullback',pullbacked:'Pulled Back',lost:'Lost'}

  const rows = items.map(a=>{
    const holderBanned = isBanned(bannedSet,a.current_holder)
    const rowBg = (holderBanned || a.current_status==='lost') ? 'var(--zinc)' : (a.current_status==='pullbacked' ? 'var(--red)' : null)
    const pbHolderClass = (holderBanned || a.current_status==='lost') ? 'text-muted' : (a.current_status==='pullbacked' ? 'text-red' : 'text-orange')
    return `<tr${rowBg?` style="background:color-mix(in oklch,${rowBg} 8%,transparent)"`:''}>
    <td>${a.pb_code?`<button class="link mono text-orange" data-action="filter-events" data-key="pb" data-val="${h(a.pb_code)}">${h(a.pb_code)}</button>`:'<span class="text-muted">—</span>'}</td>
    <td><button class="link mono" data-action="filter-events" data-key="asset" data-val="${h(a.id)}">${h(a.id)}</button></td>
    <td><div class="item-cell">${itemThumb(a.item_name)}<span>${h(a.item_name||'—')}</span></div></td>
    <td>${a.current_status==='lost' && !holderBanned ? '<span class="text-muted">—</span>' : `<button class="link ${pbHolderClass}" data-action="filter-events" data-key="holder" data-val="${h(a.current_holder)}">${h(a.current_holder||'—')}</button>${holderBanned?' <span class="badge badge-red">Banned</span>':''}`}</td>
    <td>${!a.item_holder?'<span class="text-muted">—</span>':`<button class="link text-muted" data-action="filter-events" data-key="holder" data-val="${h(a.item_holder)}">${h(a.item_holder)}</button>${isBanned(bannedSet,a.item_holder)?' <span class="badge badge-red">Banned</span>':''}${soldToMap.has(a.id)?` <span class="text-muted">→</span> <button class="link text-muted" data-action="filter-events" data-key="victim" data-val="${h(soldToMap.get(a.id))}">${h(soldToMap.get(a.id))}</button>`:''}`}</td>
    <td>${quickStatusBadge(a)}</td>
    <td class="text-muted" style="font-size:11px">${relTime(a.created_at)}</td>
    <td>
      <div style="display:flex;align-items:center;justify-content:flex-end;gap:12px">
        ${a.notes?`<span class="text-muted" style="font-size:11px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${h(a.notes)}">${h(a.notes)}</span>`:''}
        <div style="display:flex;gap:4px;flex-shrink:0">
          <button class="btn btn-ghost btn-sm" title="Edit" data-action="edit-asset" data-id="${h(a.id)}" data-holder="${h(a.current_holder)}" data-item-holder="${h(a.item_holder||'')}" data-status="${h(a.current_status)}" data-item-name="${h(a.item_name||'')}" data-context="pullback" data-notes="${h(a.notes||'')}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
          </button>
          <button class="btn btn-ghost btn-sm" title="Delete" data-action="delete-asset" data-id="${h(a.id)}" style="color:var(--red)">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg>
          </button>
        </div>
      </div>
    </td>
  </tr>`}).join('') || `<tr class="empty-row"><td colspan="8">No assets found.</td></tr>`

  mc.innerHTML = `
    <div class="page-hdr">
      <div><div class="page-title">Pullbacks</div><div class="page-sub">${items.length} asset${items.length!==1?'s':''}${_invStatus!=='ALL'?' · '+statusLabels[_invStatus]:''}${_invSearch?' · "'+h(_invSearch)+'"':''}</div></div>
      <button class="btn btn-blue" data-action="new-asset">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
        New Pullback
      </button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px">
      ${[{l:'Total',v:pbStatTotal,c:''},{l:'Pulled Back',v:pbStatPulled,c:'text-red'},{l:'Ready for Pullback',v:pbStatReady,c:'text-orange'}].map(x=>`
        <div class="card card-body" style="text-align:center;padding:16px"><div style="font-size:24px;font-weight:800" class="${x.c}">${x.v}</div><div class="text-muted" style="font-size:11px;margin-top:3px">${x.l}</div></div>`).join('')}
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search ID, holder, item…" value="${h(_invSearch)}" data-input-action="inv-search">
      </div>
      <div class="filter-row" style="margin-bottom:0">
        ${statusOpts.map(s=>`<button class="filter-chip${_invStatus===s?' active':''}" data-action="inv-status" data-status="${s}">${statusLabels[s]}</button>`).join('')}
      </div>
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th>PB ID</th><th>SS ID</th><th>Item</th><th>Pullback Holder</th><th>Item Holder</th><th>Status</th><th>Timestamp</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
}

/* — Inventory (photo catalog, aggregated per item type) —— */
let _catSearch = '', _catFilter = 'ALL'
const CAT_FILTER_LABELS = {ALL:'All',RFP:'Ready for Pullback',IN_INV:'In Inventory'}
const CAT_FILTER_LABELS_SEPARATE = [{v:'DUPED',l:'Duped (Ready to Scam)',title:'Duped copies sitting on an account, ready to use in a scam — not part of what you actually own'},{v:'LOST',l:'Lost',title:'Items marked lost — excluded from every other calculation'}]
const CAT_FILTER_LABELS_ALL = {...CAT_FILTER_LABELS, ...Object.fromEntries(CAT_FILTER_LABELS_SEPARATE.map(o=>[o.v,o.l]))}

function catRowMatches(a, filter) {
  if (filter === 'LOST') return a.current_status === 'lost'
  if (a.current_status === 'lost') return false
  if (a.current_status === 'pullbacked') return false
  const isGenuineClaim = a.current_status === 'traded' && !a.is_duped && !!a.item_holder
  if (filter === 'RFP') return isGenuineClaim
  if (filter === 'IN_INV') return a.current_status==='active' && !a.is_duped
  if (filter === 'DUPED') return (!!a.is_duped && a.current_status==='active') || (!a.is_duped && a.current_status==='traded' && !!a.item_holder)
  if (a.current_status === 'traded') return isGenuineClaim
  return !a.is_duped
}

/* — Inventory Log (every real, non-duped item you own — holder/name/status/edit) —— */
let _logSearch='', _logStatus='ALL'

async function renderInventoryLog(mc, search) {
  if (search !== undefined) _logSearch = search
  let q = '/ss_items?select=id,item_name,current_holder,current_status,is_duped,item_holder,notes,created_at&is_duped=eq.false&order=created_at.desc&limit=300'
  if (_logStatus !== 'ALL') q += `&current_status=eq.${_logStatus}`
  if (_logSearch) { const s=encodeURIComponent(_logSearch); q += `&or=(id.ilike.*${s}*,current_holder.ilike.*${s}*,item_name.ilike.*${s}*)` }
  const [itemsRaw, bannedRaw] = await Promise.all([
    sbGet(q).catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null)
  ])
  const items = itemsRaw || []
  const bannedSet = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))

  // Same status values/labels statusBadge() and the Pullbacks page already use — picking
  // a status here means the same thing it does everywhere else in the app.
  const statusOpts = ['ALL','active','traded','pullbacked','lost']
  const statusLabels = {ALL:'All',active:'In Inventory',traded:'Ready for Pullback',pullbacked:'Pulled Back',lost:'Lost'}

  const rows = items.map(a=>{
    const holderBanned = isBanned(bannedSet,a.current_holder)
    return `<tr>
      <td><button class="link mono" data-action="filter-events" data-key="asset" data-val="${h(a.id)}">${h(a.id)}</button></td>
      <td>${holderBanned?`<span class="text-muted">${h(a.current_holder||'—')} <span class="badge badge-red">Banned</span></span>`:`<button class="link" data-action="filter-events" data-key="holder" data-val="${h(a.current_holder)}">${h(a.current_holder||'—')}</button>`}</td>
      <td><div class="item-cell">${itemThumb(a.item_name)}<span>${h(a.item_name||'—')}</span></div></td>
      <td>${statusBadge(a.current_status)}</td>
      <td class="text-muted" style="font-size:11px">${fmtDate(a.created_at,true)}</td>
      <td style="font-size:11px">${h(a.notes||'—')}</td>
      <td>
        <div style="display:flex;gap:4px">
          <button class="btn btn-ghost btn-sm" title="Edit" data-action="edit-asset" data-id="${h(a.id)}" data-holder="${h(a.current_holder)}" data-item-holder="${h(a.item_holder||'')}" data-status="${h(a.current_status)}" data-item-name="${h(a.item_name||'')}" data-context="${a.item_holder?'pullback':'inventory'}" data-notes="${h(a.notes||'')}">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
          </button>
          <button class="btn btn-ghost btn-sm" title="Delete" data-action="delete-asset" data-id="${h(a.id)}" style="color:var(--red)">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg>
          </button>
        </div>
      </td>
    </tr>`
  }).join('') || `<tr class="empty-row"><td colspan="7">No items found.</td></tr>`

  mc.innerHTML = `
    <div class="page-hdr">
      <div><div class="page-title">Inventory Log</div><div class="page-sub">${items.length} item${items.length!==1?'s':''}, newest first${_logStatus!=='ALL'?' · '+statusLabels[_logStatus]:''}${_logSearch?' · "'+h(_logSearch)+'"':''}</div></div>
      <button class="btn btn-outline btn-sm" data-nav="inventory">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg>
        Back to Inventory
      </button>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search ID, holder, item…" value="${h(_logSearch)}" data-input-action="log-search">
      </div>
      <div class="filter-row" style="margin-bottom:0">
        ${statusOpts.map(s=>`<button class="filter-chip${_logStatus===s?' active':''}" data-action="log-status" data-status="${s}">${statusLabels[s]}</button>`).join('')}
      </div>
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th>SS ID</th><th>Holder</th><th>Item</th><th>Status</th><th>Timestamp</th><th>Notes</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
}

async function renderCatalog(mc, search) {
  if (search !== undefined) _catSearch = search
  const [itemsRaw, bcRaw, bannedRaw] = await Promise.all([
    sbGet('/ss_items?select=id,item_name,current_holder,current_status,is_duped,item_holder,linked_asset_id,pb_code').catch(()=>null),
    sbGet('/bc_balances?select=holder,amount').catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null)
  ])
  const items = itemsRaw || [], bcRows = bcRaw || []
  const bannedSet = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))

  let soldClaimIds = new Set(), claimsWithCopy = new Set()
  if (_catFilter === 'DUPED') {
    const claimIds = items.filter(a=>!a.is_duped && a.item_holder && a.current_status==='traded').map(a=>a.id)
    if (claimIds.length) {
      const [sold, copies] = await Promise.all([
        sbGet(`/ss_item_events?select=item_id&event_type=eq.marketplace_sale&item_id=in.(${claimIds.join(',')})`).catch(()=>null),
        sbGet(`/ss_items?select=linked_asset_id&is_duped=eq.true&linked_asset_id=in.(${claimIds.join(',')})`).catch(()=>null)
      ])
      soldClaimIds = new Set((sold||[]).map(e=>e.item_id))
      claimsWithCopy = new Set((copies||[]).map(r=>r.linked_asset_id))
    }
  }

  const groups = new Map()
  for (const a of items) {
    if (!a.item_name) continue
    if (!catRowMatches(a, _catFilter)) continue
    if (_catFilter==='DUPED' && !a.is_duped && (soldClaimIds.has(a.id) || claimsWithCopy.has(a.id))) continue
    const row = (_catFilter==='DUPED' && !a.is_duped && a.item_holder)
      ? {...a, current_holder:a.item_holder, is_duped:true, current_status:'active', item_holder:null}
      : a
    if (!groups.has(a.item_name)) groups.set(a.item_name, [])
    groups.get(a.item_name).push(row)
  }
  window._catalogGroups = groups
  window._catalogBanned = bannedSet

  let names = [...groups.keys()].sort((a,b)=>a.localeCompare(b))
  if (_catSearch) { const s=_catSearch.toLowerCase(); names = names.filter(n=>n.toLowerCase().includes(s)) }

  const bcSearchOk = !_catSearch || 'belcredits'.includes(_catSearch.toLowerCase()) || 'bc'.includes(_catSearch.toLowerCase())
  const bcTotal = _catFilter==='LOST'
    ? (bcRows||[]).filter(r=>isBanned(bannedSet,r.holder)).reduce((s,r)=>s+(r.amount||0),0)
    : (bcRows||[]).filter(r=>!isBanned(bannedSet,r.holder)).reduce((s,r)=>s+(r.amount||0),0)
  const bcVisible = bcSearchOk && _catFilter!=='DUPED' && bcTotal>0
  const bcImg = (window._catalogImages||{})['Belcredits']
  const bcCard = bcVisible ? `<div class="cat-card" data-action="open-bc-modal">
      <span class="cat-qty">${bcTotal.toLocaleString()}</span>
      <div class="cat-thumb">${bcImg?`<img src="${h(bcImg)}" alt="">`:`<span class="cat-thumb-ph">BC</span>`}</div>
      <div class="cat-name">Belcredits</div>
    </div>` : ''

  const cards = names.map(name => {
    const rows = groups.get(name)
    const img = (window._catalogImages||{})[name]
    return `<div class="cat-card" data-action="open-cat-item" data-name="${h(name)}">
      <span class="cat-qty">${rows.length}</span>
      <div class="cat-thumb">${img?`<img src="${h(img)}" alt="">`:`<span class="cat-thumb-ph">?</span>`}</div>
      <div class="cat-name">${h(name)}</div>
    </div>`
  }).join('')

  const cardsHtml = (bcCard + cards) || `<div style="grid-column:1/-1;text-align:center;color:var(--muted);padding:48px;font-size:13px">${_catSearch?'No items matching.':'No items owned yet.'}</div>`

  mc.innerHTML = `
    <div class="page-hdr">
      <div><div class="page-title">Inventory</div><div class="page-sub">${names.length} item type${names.length!==1?'s':''}${_catFilter!=='ALL'?' · '+CAT_FILTER_LABELS_ALL[_catFilter]:''}</div></div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-outline" data-nav="invlog">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
          Log
        </button>
        <button class="btn btn-green" data-action="open-import-item">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
          New Item
        </button>
      </div>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search item…" value="${h(_catSearch)}" data-input-action="cat-search">
      </div>
      <div class="filter-row" style="margin-bottom:0">
        ${Object.keys(CAT_FILTER_LABELS).map(f=>`<button class="filter-chip${_catFilter===f?' active':''}" data-action="cat-filter" data-filter="${f}">${CAT_FILTER_LABELS[f]}</button>`).join('')}
        ${CAT_FILTER_LABELS_SEPARATE.map(o=>`<span style="width:1px;height:18px;background:var(--border);margin:0 2px"></span><button class="filter-chip${_catFilter===o.v?' active':''}" data-action="cat-filter" data-filter="${o.v}" title="${h(o.title)}">${o.l}</button>`).join('')}
      </div>
    </div>
    <div class="cat-grid">${cardsHtml}</div>`
}

function openCatItemModal(name) {
  const rows = (window._catalogGroups && window._catalogGroups.get(name)) || []
  const byHolder = new Map()
  for (const r of rows) {
    const key = (r.current_holder||'').toLowerCase()
    if (!byHolder.has(key)) byHolder.set(key, {holder:r.current_holder, inv:0, rfp:0, duped:0, lost:0, codeRows:[]})
    const b = byHolder.get(key)
    if (r.current_status === 'lost') { b.lost++; continue }
    if (r.is_duped && r.current_status === 'traded') continue
    if (r.current_status === 'traded') { b.rfp++; b.codeRows.push(r); continue }
    if (r.current_status === 'pullbacked') continue
    if (r.item_holder) continue
    if (r.is_duped) { b.duped++; b.codeRows.push(r); continue }
    b.inv++
  }
  const codeChips = list => list.map(r => {
    const ss = `<button class="link mono" style="font-size:10px" data-action="filter-events" data-key="asset" data-val="${h(r.id)}">${h(r.id)}</button>`
    const pb = r.pb_code ? ` <button class="link mono" style="font-size:10px;color:var(--orange)" data-action="filter-events" data-key="pb" data-val="${h(r.pb_code)}">${h(r.pb_code)}</button>` : ''
    return ss+pb
  }).join(' ')
  const list = [...byHolder.values()].filter(c=>c.inv||c.rfp||c.duped||c.lost).map(c => {
    const holder = c.holder
    const parts = []
    if (c.inv) parts.push(`<span class="badge badge-green">${c.inv} In Inventory</span>`)
    if (c.rfp) parts.push(`<span class="badge badge-orange">${c.rfp} Ready for Pullback</span>`)
    if (c.duped) parts.push(`<span class="badge badge-zinc">${c.duped} Duped</span>`)
    if (c.lost) parts.push(`<span class="badge badge-zinc">${c.lost} Lost${isBanned(window._catalogBanned,holder)?' (Banned)':''}</span>`)
    const holderBannedCat = isBanned(window._catalogBanned,holder)
    const nameCell = (c.lost && !c.inv && !c.rfp && !c.duped && !holderBannedCat)
      ? '<span class="text-muted">—</span>'
      : `<button class="link" data-action="filter-events" data-key="holder" data-val="${h(holder)}">${h(holder)}</button>`
    const codes = codeChips(c.codeRows)
    return `<div class="sum-row" style="flex-direction:column;align-items:stretch;gap:4px">
      <div style="display:flex;align-items:center;justify-content:space-between">${nameCell}<div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end">${parts.join('')}</div></div>
      ${codes?`<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end">${codes}</div>`:''}
    </div>`
  }).join('') || '<div class="text-muted" style="font-size:12px;padding:12px 0;text-align:center">No items owned.</div>'

  const img = (window._catalogImages||{})[name]
  const unitVal = (window._catalogValues||{})[name]
  // A pullback claim and its duped copy (doCreatePullbackAsset always creates both —
  // one tracks who's chasing it, the other who physically holds it) are two DB rows
  // for the SAME real item. The per-holder breakdown above intentionally counts both
  // (shows both sides), but the Total up top was double-counting every such pair.
  const claimIds = new Set(rows.filter(r=>!r.is_duped && r.item_holder).map(r=>r.id))
  let total = 0
  for (const r of rows) {
    if (r.current_status === 'pullbacked') continue
    if (r.is_duped && r.linked_asset_id && claimIds.has(r.linked_asset_id)) continue
    total++
  }
  openModal(name, `
    ${img?`<div style="width:100%;aspect-ratio:2/1;background:var(--input);border-radius:8px;display:flex;align-items:center;justify-content:center;overflow:hidden;margin-bottom:12px"><img src="${h(img)}" style="width:100%;height:100%;object-fit:contain;image-rendering:pixelated;image-rendering:-moz-crisp-edges;image-rendering:crisp-edges"></div>`:''}
    <div style="margin-bottom:10px;font-size:12px;color:var(--muted)">Total: <strong style="color:var(--text)">${total}</strong>${unitVal!=null?` <span style="margin-left:8px">Value: <strong class="text-yellow">${(unitVal*total).toLocaleString()} BC</strong> <span style="color:var(--muted)">(${unitVal.toLocaleString()}/ea)</span></span>`:''}</div>
    ${list}`, [{label:'Close',fn:closeModal}])
}

/* — Belcredits balances ———————————————————————————— */
async function openBcModal() {
  window._bcRows = await sbGet('/bc_balances?select=holder,amount&order=amount.desc').catch(()=>[]) || []
  renderBcModal()
}

function renderBcModal() {
  const rows = window._bcRows || []
  const total = rows.reduce((s,r)=>s+(r.amount||0),0)
  const list = rows.map(r=>`
    <div class="catimg-row">
      <div class="catimg-name" style="flex:1;font-weight:600">${h(r.holder)}</div>
      <span class="text-yellow" style="font-weight:700">${(r.amount||0).toLocaleString()} BC</span>
    </div>`).join('') || '<div class="text-muted" style="font-size:12px;padding:12px 0;text-align:center">No balances yet.</div>'

  openModal('Belcredits', `
    <div style="margin-bottom:10px;font-size:12px;color:var(--muted)">Total: <strong class="text-yellow" style="font-size:16px">${total.toLocaleString()} BC</strong></div>
    <div class="catimg-list" style="max-height:320px">${list}</div>
    <div style="margin-top:12px;font-size:11px;color:var(--muted);text-align:center">Calculated from trade history — add or edit a trade's BC Received to change it.</div>`, [{label:'Close', fn:closeModal}])
}

/* — Scammed ———————————————————————————————— */
let _scamSearch = ''
// Defaults to hiding plain acquisitions (earned/hacked/bought/friendly — not real scams,
// this is what cluttered the table with rows like "New Earned" and mostly "—" columns)
// so Trades reads as actual trades by default. Still one click away via the filter chip;
// the full acquisition trail lives in the Inventory Log instead.
let _scamFilter = 'SCAMMED'
const SCAM_LEGIT_TYPES = new Set(['earned','bought','friendly','hacked'])
const SCAM_FILTER_LABELS = {ALL:'All', SCAMMED:'Scammed', EARNED:'Earned'}
async function renderScammed(mc, search) {
  if (search !== undefined) _scamSearch = search
  const [scamEvts, pullbackEvts, bannedRaw] = await Promise.all([
    sbGet('/ss_item_events?select=id,item_id,reason,trade_code,scammed_user,to_holder,bc_amount,bc_given,notes,items_given,items_received,scam_type,event_type,from_holder,timestamp,bc_counted,bc_given_counted&event_type=eq.marketplace_sale&order=timestamp.desc'),
    sbGet('/ss_item_events?select=id,item_id,event_type,to_holder,from_holder,notes,timestamp&event_type=eq.pullback&order=timestamp.desc').catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null)
  ])
  const bannedSet = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))
  const scams=scamEvts||[]
  const pullbacks=pullbackEvts||[]
  window._evData=window._evData||{}
  for(const e of scams) window._evData[e.id]=e
  for(const e of pullbacks) window._evData[e.id]=e
  const byReason = new Map(), singles = []
  for (const e of scams) {
    if (e.reason) { if (!byReason.has(e.reason)) byReason.set(e.reason, []); byReason.get(e.reason).push(e) }
    else singles.push(e)
  }
  const grouped = [...singles, ...[...byReason.values()].map(evs => {
    if (evs.length === 1) return evs[0]
    const primary = evs.find(e=>e.bc_amount!=null || e.bc_given!=null || e.items_received!=null || e.notes!=null) || evs[0]
    const allGiven = evs.map(e=>e.items_given).filter(Boolean).join(', ')
    return {...primary, items_given: allGiven || primary.items_given, _batchItemIds: evs.map(e=>e.item_id).filter(Boolean)}
  })]
  grouped.sort((a,b)=>new Date(b.timestamp)-new Date(a.timestamp))

  const seen=new Set(), unique=[]
  for(const e of grouped){const key=e.item_id??e.id; if(!seen.has(key)){seen.add(key);unique.push(e)}}

  const ids=[...new Set([...unique.map(e=>e.item_id), ...unique.flatMap(e=>e._batchItemIds||[]), ...pullbacks.map(e=>e.item_id)].filter(Boolean))]
  let itemMap=new Map()
  if(ids.length){const items=await sbGet(`/ss_items?select=id,item_name,current_holder,current_status,linked_asset_id,is_duped,item_holder,notes,pb_code&id=in.(${ids.join(',')})`)||[];items.forEach(a=>itemMap.set(a.id,a))}

  const linkIds=[...itemMap.values()].map(a=>a.linked_asset_id).filter(Boolean)
  let linkMap=new Map()
  if(linkIds.length){const linked=await sbGet(`/ss_items?select=id,current_status,current_holder,notes,pb_code,item_holder&id=in.(${linkIds.join(',')})`)||[];linked.forEach(a=>linkMap.set(a.id,a))}

  const isPulled=(a)=>{
    if(!a) return false
    if(a.current_status==='pullbacked') return true
    if(a.is_duped && a.linked_asset_id && linkMap.get(a.linked_asset_id)?.current_status==='pullbacked') return true
    return false
  }

  const notLost=unique.filter(e=>itemMap.get(e.item_id)?.current_status!=='lost')
  const totalEarned=notLost.filter(e=>SCAM_LEGIT_TYPES.has(e.scam_type)).length
  const totalScammed=notLost.length-totalEarned

  const searchTerm = _scamSearch.trim().toLowerCase()
  const scored = unique.map(e=>{
    const a=itemMap.get(e.item_id)||{}
    const given = parseItemList(e.items_given)
    const received = parseItemList(e.items_received)
    const isLinkedDupe = a.is_duped && a.linked_asset_id
    const pullbackClaimStatus = isLinkedDupe ? linkMap.get(a.linked_asset_id)?.current_status : (!a.is_duped && a.item_holder ? a.current_status : null)
    const pullbackHolder = isLinkedDupe ? linkMap.get(a.linked_asset_id)?.current_holder : (['traded','pullbacked','lost'].includes(pullbackClaimStatus) ? a.current_holder : null)
    const isAcquisitionType = e.scam_type==='hacked' || e.scam_type==='earned' || e.scam_type==='bought'
    const batchIds = isAcquisitionType ? [] : (e._batchItemIds || (e.item_id ? [e.item_id] : []))
    const pbEntriesMap = new Map()
    const givenHolders = []
    const givenInfo = []
    for (const id of batchIds) {
      const item = itemMap.get(id) || {}
      const linked = item.is_duped && item.linked_asset_id
      const claim = linked ? linkMap.get(item.linked_asset_id) : null
      const status = linked ? claim?.current_status : (!item.is_duped && item.item_holder ? item.current_status : null)
      const holder = linked ? claim?.current_holder : (['traded','pullbacked','lost'].includes(status) ? item.current_holder : null)
      givenHolders.push(status==='traded' ? holder : null)
      if (holder && !pbEntriesMap.has(holder)) pbEntriesMap.set(holder, status)
      givenInfo.push({
        ss: linked ? item.linked_asset_id : (item.id||id),
        pb: linked ? (claim?.pb_code||null) : (item.pb_code||null),
        itemHolder: linked ? (claim?.item_holder||null) : (item.item_holder||null),
        status: linked ? claim?.current_status : item.current_status,
        holder
      })
    }
    const pbEntries = [...pbEntriesMap.entries()].map(([holder,status])=>({holder,status}))
    const fromHolder = e.from_holder || (e.scam_type==='earned' ? null : a.current_holder)
    const pullTargetId = isAcquisitionType ? null : (isLinkedDupe ? a.linked_asset_id : (!a.is_duped && a.item_holder && a.current_status==='traded' ? a.id : null))
    const searchText = [a.id,a.item_name,fromHolder,...pbEntries.map(p=>p.holder),e.scammed_user,e.notes,SCAM_TYPE_LABELS[e.scam_type],fmtDate(e.timestamp,true),...given,...received].filter(Boolean).join(' ').toLowerCase()
    return {e,a,given,received,pullbackHolder,pullbackClaimStatus,pbEntries,givenHolders,givenInfo,fromHolder,pullTargetId,searchText}
  })
  let filtered = searchTerm ? scored.filter(r=>r.searchText.includes(searchTerm)) : scored
  if (_scamFilter==='EARNED') filtered = filtered.filter(r=>SCAM_LEGIT_TYPES.has(r.e.scam_type))
  else if (_scamFilter==='SCAMMED') filtered = filtered.filter(r=>!SCAM_LEGIT_TYPES.has(r.e.scam_type))

  let pullbackRows = []
  if (_scamFilter==='ALL') {
    pullbackRows = pullbacks.map(e=>{
      const a=itemMap.get(e.item_id)||{}
      const searchText=[a.item_name,e.to_holder,e.from_holder,e.notes,'pulled back',fmtDate(e.timestamp,true)].filter(Boolean).join(' ').toLowerCase()
      return {kind:'pullback',e,a,searchText}
    })
    if (searchTerm) pullbackRows = pullbackRows.filter(r=>r.searchText.includes(searchTerm))
  }
  const combined = [...filtered.map(r=>({kind:'trade',...r})), ...pullbackRows].sort((x,y)=>new Date(y.e.timestamp)-new Date(x.e.timestamp))

  window._tradeRowData = new Map()
  const rows=combined.map(row=>{
    if (row.kind==='pullback') {
      const {e,a} = row
      const codeBtns = [
        a.id?`<button class="link mono" style="font-size:11px" data-action="filter-events" data-key="asset" data-val="${h(a.id)}">${h(a.id)}</button>`:'',
        a.pb_code?`<button class="link mono" style="font-size:11px;color:var(--orange)" data-action="filter-events" data-key="pb" data-val="${h(a.pb_code)}">${h(a.pb_code)}</button>`:''
      ].filter(Boolean).join(' ')
      return `<tr style="background:color-mix(in oklch,var(--orange) 8%,transparent)">
      <td><span class="text-muted">—</span></td>
      <td><span class="badge" style="background:color-mix(in oklch,var(--orange) 18%,transparent);color:var(--orange)">Pulled Back</span></td>
      <td>${e.from_holder?`<button class="link text-orange" data-action="filter-events" data-key="holder" data-val="${h(e.from_holder)}">${h(e.from_holder)}</button>`:'<span class="text-muted">—</span>'}</td>
      <td><span class="text-muted">—</span></td>
      <td><span class="text-muted">—</span></td>
      <td><div class="item-cell">${itemThumb(a.item_name)}<span>${h(a.item_name||'—')}</span></div></td>
      <td class="text-muted" style="font-size:11px">${fmtDate(e.timestamp,true)}</td>
      <td><span class="badge badge-green">Yes</span></td>
      <td>
        <div style="display:flex;align-items:center;justify-content:flex-end;gap:12px">
          <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;justify-content:flex-end;flex:1;min-width:0">
            ${codeBtns}
            ${e.notes?`<span class="text-muted" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${h(e.notes)}">${h(e.notes)}</span>`:''}
          </div>
          <div style="display:flex;gap:4px;flex-shrink:0">
            <button class="btn btn-ghost btn-sm" title="Edit" data-action="edit-event" data-id="${h(e.id)}">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="btn btn-ghost btn-sm" title="Delete" data-action="delete-event" data-id="${h(e.id)}" style="color:var(--red)">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg>
            </button>
          </div>
        </div>
      </td>
    </tr>`
    }
    const {e,a,given,received,pullbackHolder,pbEntries,givenHolders,givenInfo,fromHolder,pullTargetId} = row
    const bc = e.bc_amount!=null ? `<span class="text-yellow" style="font-size:11px;font-weight:700">+${e.bc_amount.toLocaleString()} BC</span>` : ''
    const bcGiven = e.bc_given!=null ? `<span class="text-yellow" style="font-size:11px;font-weight:700">-${e.bc_given.toLocaleString()} BC</span>` : ''
    const fromBanned = isBanned(bannedSet,fromHolder)
    const rowIsPulled = (e.scam_type==='hacked' || e.scam_type==='earned' || e.scam_type==='bought') ? false : isPulled(a)
    const rowBg = (fromBanned || a.current_status==='lost') ? 'var(--zinc)' : (rowIsPulled ? 'var(--red)' : null)
    const pbCells = pbEntries.map(({holder,status})=>{
      const banned = isBanned(bannedSet,holder)
      const hidden = status==='lost' && !banned
      if (hidden) return null
      const cls = status==='lost' ? 'text-muted' : (status==='pullbacked' ? 'text-red' : 'text-orange')
      return `<button class="link ${cls}" data-action="filter-events" data-key="holder" data-val="${h(holder)}">${h(holder)}</button>${banned?' <span class="badge badge-red">Banned</span>':''}`
    }).filter(Boolean)
    const claimNotes = a.linked_asset_id ? linkMap.get(a.linked_asset_id)?.notes : a.notes
    const claimNotesItemId = a.linked_asset_id || a.id || null
    const rowNoteBits = claimNotes || e.notes || ''
    const anchorCodes = (a.is_duped && a.linked_asset_id)
      ? {ss: a.linked_asset_id, pb: linkMap.get(a.linked_asset_id)?.pb_code || null}
      : {ss: a.id || null, pb: a.pb_code || null}
    window._tradeRowData.set(e.id, {a,given,received,bc,bcGiven,pullbackHolder,givenHolders,givenInfo,fromHolder,claimNotes,claimNotesItemId,tradeCode:e.trade_code,ssId:anchorCodes.ss,pbCode:anchorCodes.pb})
    return `<tr${rowBg?` style="background:color-mix(in oklch,${rowBg} 8%,transparent)"`:''}>
      <td class="mono text-muted" style="font-size:11px">${e.trade_code?`<button class="link mono" style="font-size:11px" data-action="filter-events" data-key="trade" data-val="${h(e.trade_code)}">${h(e.trade_code)}</button>`:'—'}</td>
      <td>${eventBadge('marketplace_sale',null,e.scam_type)}</td>
      <td>${pbCells.length?pbCells.join('<span class="text-muted">, </span>'):'<span class="text-muted">—</span>'}</td>
      <td>${e.scam_type==='friendly'&&e.to_holder?`${h(fromHolder||'—')} <span class="text-muted">→</span> ${h(e.to_holder)}`
        :h(fromHolder||'—')}${fromBanned?' <span class="badge badge-red">Banned</span>':''}</td>
      <td>${!e.scammed_user?'<span class="text-muted">—</span>'
        :e.scammed_user==='/'?`<span class="text-muted" title="Niet-klikbaar: geen echte victim, gebruikt om de BC counter recht te zetten">/</span>`
        :`<button class="link ${a.current_status==='lost'?'text-muted':'text-red'}" data-action="filter-events" data-key="victim" data-val="${h(e.scammed_user)}">${h(e.scammed_user)}</button>`}</td>
      <td><button class="btn btn-outline btn-sm" data-action="open-trade-detail" data-id="${h(e.id)}">Details</button></td>
      <td class="text-muted" style="font-size:11px">${fmtDate(e.timestamp,true)}</td>
      <td>${fromBanned ? '<span class="text-muted">—</span>' : isPulled(a)
        ?'<span class="badge badge-green">Yes</span>'
        :pullTargetId
          ?`<button class="badge badge-red" style="cursor:pointer;font:inherit;font-size:10px;font-weight:700" data-action="mark-trade-pulled" data-id="${h(pullTargetId)}" data-holder="${h(pullbackHolder||'')}" data-item-name="${h(a.item_name||'')}">No</button>`
          :'<span class="badge badge-red">No</span>'}</td>
      <td>
        <div style="display:flex;align-items:center;justify-content:flex-end;gap:12px">
          ${rowNoteBits?`<span class="text-muted" style="font-size:11px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${h(rowNoteBits)}">${h(rowNoteBits)}</span>`:''}
          <div style="display:flex;gap:4px;flex-shrink:0">
            <button class="btn btn-ghost btn-sm" title="Edit" data-action="edit-event" data-id="${h(e.id)}">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </button>
            <button class="btn btn-ghost btn-sm" title="Delete" data-action="delete-event" data-id="${h(e.id)}" style="color:var(--red)">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg>
            </button>
          </div>
        </div>
      </td>
    </tr>`}).join('')||'<tr class="empty-row"><td colspan="9">No trades.</td></tr>'

  mc.innerHTML=`
    <div class="page-hdr">
      <div><div class="page-title">Trades</div><div class="page-sub">${filtered.length} trade${filtered.length!==1?'s':''}${_scamSearch?' · "'+h(_scamSearch)+'"':''}</div></div>
      <button class="btn btn-danger" data-action="open-scam-import">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="13" height="13"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
        New Trade
      </button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px">
      ${[{l:'Total Trades',v:notLost.length,c:''},{l:'Total Items Earned',v:totalEarned,c:'text-green'},{l:'Total Scammed',v:totalScammed,c:'text-red'}].map(x=>`
        <div class="card card-body" style="text-align:center;padding:16px"><div style="font-size:24px;font-weight:800" class="${x.c}">${x.v}</div><div class="text-muted" style="font-size:11px;margin-top:3px">${x.l}</div></div>`).join('')}
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search anything: id, item, holder, victim, notes…" value="${h(_scamSearch)}" data-input-action="scam-search">
      </div>
      <div class="filter-row" style="margin-bottom:0">
        ${Object.keys(SCAM_FILTER_LABELS).map(f=>`<button class="filter-chip${_scamFilter===f?' active':''}" data-action="scam-filter" data-filter="${f}">${SCAM_FILTER_LABELS[f]}</button>`).join('')}
      </div>
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th>Trade</th><th>Type</th><th>Pullback Holder</th><th>Item Holder</th><th>Victim</th><th>Items Traded</th><th>Date</th><th>Pulled?</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
}

function wireTradeItemPopovers() {
  document.querySelectorAll('.trade-items-trigger').forEach(trigger => {
    const btn = trigger.querySelector('button')
    const content = trigger.querySelector('.trade-items-content')
    if (!btn || !content) return
    let popEl = null
    btn.addEventListener('mouseenter', () => {
      const rect = btn.getBoundingClientRect()
      popEl = document.createElement('div')
      popEl.className = 'trade-items-popover'
      popEl.innerHTML = content.innerHTML
      document.body.appendChild(popEl)
      const popRect = popEl.getBoundingClientRect()
      let top = rect.bottom + 6
      if (top + popRect.height > window.innerHeight) top = rect.top - popRect.height - 6
      let left = rect.left
      if (left + popRect.width > window.innerWidth) left = window.innerWidth - popRect.width - 10
      popEl.style.top = Math.max(4,top) + 'px'
      popEl.style.left = Math.max(4,left) + 'px'
    })
    btn.addEventListener('mouseleave', () => { if (popEl) { popEl.remove(); popEl=null } })
  })
}

/* — Victims —————————————————————————————————— */
let _victimSearch = ''
async function renderVictims(mc, search) {
  if (search !== undefined) _victimSearch = search
  const ev=(await sbGet('/ss_item_events?select=scammed_user,bc_amount,item_id,timestamp&event_type=eq.marketplace_sale&scammed_user=not.is.null')||[]).filter(e=>e.scammed_user!=='/')
  const itemIds=[...new Set(ev.map(e=>e.item_id).filter(Boolean))]
  const itemNameMap=new Map()
  if(itemIds.length){const items=await sbGet(`/ss_items?select=id,item_name&id=in.(${itemIds.join(',')})`)||[];items.forEach(a=>itemNameMap.set(a.id,a.item_name))}

  const map=new Map()
  for(const e of ev){
    const u=e.scammed_user
    if(!map.has(u))map.set(u,{bc:0,itemNames:[],last:e.timestamp})
    const r=map.get(u)
    r.bc+=e.bc_amount||0
    const name=itemNameMap.get(e.item_id)
    if(name)r.itemNames.push(name)
    if(e.timestamp>r.last)r.last=e.timestamp
  }
  let victims=[...map.entries()].map(([user,v])=>({user,bc:v.bc,itemNames:v.itemNames,last:v.last})).sort((a,b)=>new Date(b.last)-new Date(a.last))
  if (_victimSearch) { const s=_victimSearch.toLowerCase(); victims=victims.filter(v=>v.user.toLowerCase().includes(s)) }

  const totalItems=victims.reduce((s,v)=>s+v.itemNames.length,0)
  const totalBc=victims.reduce((s,v)=>s+v.bc,0)

  const rows=victims.map(v=>`<tr>
    <td style="padding-right:28px"><button class="link" data-action="filter-events" data-key="victim" data-val="${h(v.user)}">${h(v.user)}</button>${renameHolderBtn(v.user)}</td>
    <td style="text-align:right;padding-right:28px">${holderItemsCell(v.itemNames,'text-red')}</td>
    <td style="text-align:right;padding-right:28px">${v.bc>0?`<span class="text-yellow">${v.bc.toLocaleString()}</span>`:''}</td>
    <td class="text-muted" style="font-size:11px">${relTime(v.last)}</td>
    <td style="text-align:right"><button class="link" data-action="filter-events" data-key="victim" data-val="${h(v.user)}">Details</button></td>
  </tr>`).join('')||'<tr class="empty-row"><td colspan="5">No scams.</td></tr>'

  mc.innerHTML=`
    <div class="page-hdr"><div><div class="page-title">Victims</div><div class="page-sub">${victims.length}${_victimSearch?' · "'+h(_victimSearch)+'"':''}</div></div></div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:16px">
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--pink)">${victims.length}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Unique Victims</div></div>
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--red)">${totalItems}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Total Items Scammed</div></div>
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--yellow)">${totalBc.toLocaleString()}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Total BC Scammed</div></div>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search victim…" value="${h(_victimSearch)}" data-input-action="victim-search">
      </div>
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th style="padding-right:28px">Victim</th><th style="text-align:right;padding-right:28px">Scammed</th><th style="text-align:right;padding-right:28px">BC</th><th>Last Activity</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
  wireTradeItemPopovers()
}

/* — Holders —————————————————————————————————— */
let _holderFilter = 'ALL'
const HOLDER_FILTER_LABELS = {ALL:'All',RFP:'Ready for Pullback',INV:'In Inventory',LOST:'Lost'}

function renameHolderBtn(name) {
  return `<button class="btn btn-ghost btn-sm" title="Rename" data-action="rename-holder" data-holder="${h(name)}" style="padding:2px;margin-left:2px">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="11" height="11"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
  </button>`
}

function openRenameHolderModal(oldName) {
  openModal('Rename Account', `
    <p style="font-size:12px;color:var(--muted);margin-bottom:12px">Renames <strong class="mono" style="color:var(--text)">${h(oldName)}</strong> everywhere — Inventory, Pullbacks, Trades, Belcredits, bans — to the new name.</p>
    <div class="form-group"><label>New Name *</label><input type="text" id="m-new-holder-name" value="${h(oldName)}" autofocus></div>`,
  [{label:'Cancel',fn:closeModal},{label:'Rename',cls:'btn-primary',fn:async()=>{
    const newName = document.getElementById('m-new-holder-name').value.trim()
    if (!newName) return modalError('Enter a name.')
    if (newName === oldName) return modalError('That\'s already the current name.')
    setBtn(1,'Renaming…',true)
    try { await doRenameHolder(oldName, newName); closeModal(); route() }
    catch(e) { modalError(e.message); setBtn(1,'Rename',false) }
  }}])
}

function holderItemsCell(items, extraClass) {
  if (!items.length) return ''
  return `<span class="trade-items-trigger">
    <button type="button" class="holder-count-btn ${extraClass}">${items.length}</button>
    <div class="trade-items-content" hidden>
      <div style="display:flex;flex-direction:column;gap:6px">
        ${items.map(n=>tradeItemRow(n)).join('')}
      </div>
    </div>
  </span>`
}

/* — Holder Details (their actual inventory, not the event log) ——————————— */
function openHolderItemsModal(holder) {
  window._holderItemsHolder = holder
  window._holderItemsList = null
  window._holderItemsActive = null
  renderHolderItemsModal()
  sbGet(`/ss_items?select=id,item_name,pb_code&current_status=eq.active&is_duped=eq.false&current_holder=ilike.${encodeURIComponent(holder)}&order=item_name`)
    .then(rows => { window._holderItemsList = rows||[]; renderHolderItemsModal() })
    .catch(e => { window._holderItemsList = []; renderHolderItemsModal(); modalError(e.message) })
}

function renderHolderItemsModal() {
  const holder = window._holderItemsHolder
  const list = window._holderItemsList
  const active = window._holderItemsActive
  let body
  if (list === null) {
    body = `<div class="loading">Loading…</div>`
  } else if (!list.length) {
    body = `<div class="text-muted" style="text-align:center;padding:24px 0">Nothing In Inventory for ${h(holder)}.</div>`
  } else {
    const rows = list.map(a => `
      <div class="ac-item" data-action="show-holder-item" data-id="${h(a.id)}" style="${active===a.id?'background:var(--accent)':''}">
        ${itemThumb(a.item_name)}<span>${h(a.item_name)}</span>
      </div>`).join('')
    let infoHtml = ''
    const a = active && list.find(x=>x.id===active)
    if (a) {
      infoHtml = `<div class="card" style="margin-top:12px"><div class="card-body" style="padding:12px">
        <div class="sum-row"><span class="sum-label">Item</span><strong>${h(a.item_name)}</strong></div>
        <div class="sum-row"><span class="sum-label">SS ID</span><button class="link mono" data-action="filter-events" data-key="asset" data-val="${h(a.id)}">${h(a.id)}</button></div>
        ${a.pb_code?`<div class="sum-row"><span class="sum-label">PB ID</span><button class="link mono text-orange" data-action="filter-events" data-key="pb" data-val="${h(a.pb_code)}">${h(a.pb_code)}</button></div>`:''}
      </div></div>`
    }
    body = `<div style="display:flex;flex-direction:column;gap:2px;max-height:360px;overflow:auto">${rows}</div>${infoHtml}`
  }
  openModal(`${holder} — Inventory`, body, [{label:'Close', fn:closeModal}])
}

let _holderSearch = ''
async function renderHolders(mc, search) {
  if (search !== undefined) _holderSearch = search
  const [itemsRaw, bannedRaw, evRaw, bcRaw] = await Promise.all([
    sbGet('/ss_items?select=current_holder,current_status,id,is_duped,item_name,created_at').catch(()=>null),
    sbGet('/banned_holders?select=holder').catch(()=>null),
    sbGet('/ss_item_events?select=to_holder,timestamp&to_holder=not.is.null').catch(()=>null),
    sbGet('/bc_balances?select=holder,amount').catch(()=>null)
  ])
  const items = itemsRaw||[]
  const banned = new Set((bannedRaw||[]).map(r=>(r.holder||'').toLowerCase()))
  const bcMap = new Map((bcRaw||[]).map(r=>[(r.holder||'').toLowerCase(), r.amount]))
  const lastActivity = new Map()
  const bump = (holder, ts) => { if (!holder || !ts) return; const key=holder.toLowerCase(); const cur=lastActivity.get(key); if (!cur || ts>cur) lastActivity.set(key, ts) }
  // Grouped case-insensitively — "Ravenclaw221" and "ravenclaw221" are the same real
  // person, and used to show up as two separate rows here. First-seen casing wins for
  // display.
  const map=new Map()
  for(const a of items){
    if(!a.current_holder) continue
    const key = a.current_holder.toLowerCase()
    if(!map.has(key))map.set(key,{holder:a.current_holder,inv:0,rfp:0,lost:0,total:new Set(),invItems:[],rfpItems:[],lostItems:[]})
    const r=map.get(key)
    if(a.current_status!=='lost')r.total.add(a.id)
    if(a.current_status==='active'&&!a.is_duped){r.inv++;r.invItems.push(a.item_name)}
    else if(a.current_status==='traded'&&!a.is_duped){r.rfp++;r.rfpItems.push(a.item_name)}
    else if(a.current_status==='lost'){r.lost++;r.lostItems.push(a.item_name)}
    bump(a.current_holder, a.created_at)
  }
  for (const e of (evRaw||[])) bump(e.to_holder, e.timestamp)
  let holders=[...map.entries()].map(([key,v])=>({holder:v.holder,inv:v.inv,rfp:v.rfp,lost:v.lost,invItems:v.invItems,rfpItems:v.rfpItems,lostItems:v.lostItems,total:v.total.size,banned:isBanned(banned,v.holder),lastActivity:lastActivity.get(key)||''})).sort((a,b)=>b.lastActivity<a.lastActivity?-1:b.lastActivity>a.lastActivity?1:0)

  const allHolders = holders
  if (_holderFilter==='RFP') holders = holders.filter(x=>x.rfp>0)
  else if (_holderFilter==='INV') holders = holders.filter(x=>x.inv>0)
  else if (_holderFilter==='LOST') holders = holders.filter(x=>x.lost>0)
  if (_holderSearch) { const s=_holderSearch.toLowerCase(); holders = holders.filter(x=>x.holder.toLowerCase().includes(s)) }

  const rows=holders.map(hld=>{
    const isLostSentinel = hld.holder && hld.holder.trim().toLowerCase()==='lost'
    return `<tr>
    <td style="padding-right:28px"><button class="link${isLostSentinel?' text-muted':''}" data-action="filter-events" data-key="holder" data-val="${h(hld.holder)}">${h(hld.holder)}</button>${renameHolderBtn(hld.holder)}</td>
    <td style="padding-right:28px">
      ${hld.banned
        ?`<button class="btn btn-outline btn-sm" data-action="unban-holder" data-holder="${h(hld.holder)}">Unban</button>`
        :`<button class="btn btn-danger btn-sm" data-action="ban-holder" data-holder="${h(hld.holder)}">Mark as Banned</button>`}
    </td>
    <td style="text-align:right;padding-right:28px">${holderItemsCell(hld.invItems, hld.inv>0?'text-green':'')}</td>
    <td style="text-align:right;padding-right:28px">${holderItemsCell(hld.rfpItems, hld.rfp>0?'text-orange':'')}</td>
    <td style="text-align:right;padding-right:28px">${holderItemsCell(hld.lostItems, hld.lost>0?'text-muted':'')}</td>
    <td style="text-align:right;padding-right:28px">${bcMap.get(hld.holder.toLowerCase())?`<span class="text-yellow">${bcMap.get(hld.holder.toLowerCase()).toLocaleString()}</span>`:''}</td>
    <td style="text-align:right"><button class="link" data-action="open-holder-items" data-holder="${h(hld.holder)}">Details</button></td>
  </tr>`}).join('')||'<tr class="empty-row"><td colspan="7">No holders.</td></tr>'

  mc.innerHTML=`
    <div class="page-hdr"><div><div class="page-title">Holders</div><div class="page-sub">${holders.length}${_holderFilter!=='ALL'?' · '+HOLDER_FILTER_LABELS[_holderFilter]:''}${_holderSearch?' · "'+h(_holderSearch)+'"':''}</div></div></div>
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:10px;margin-bottom:16px">
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--primary)">${allHolders.length}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Total Holders</div></div>
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--green)">${allHolders.reduce((s,x)=>s+x.inv,0)}</div><div class="text-muted" style="font-size:11px;margin-top:3px">In Inventory</div></div>
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--orange)">${allHolders.reduce((s,x)=>s+x.rfp,0)}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Ready for Pullback</div></div>
      <div class="card card-body" style="padding:16px"><div style="font-size:24px;font-weight:800;color:var(--zinc)">${allHolders.reduce((s,x)=>s+x.lost,0)}</div><div class="text-muted" style="font-size:11px;margin-top:3px">Lost</div></div>
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap">
      <div class="search-input" style="flex:1;min-width:200px">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="Search holder…" value="${h(_holderSearch)}" data-input-action="holder-search">
      </div>
      <div class="filter-row" style="margin-bottom:0">
        ${Object.keys(HOLDER_FILTER_LABELS).map(f=>`<button class="filter-chip${_holderFilter===f?' active':''}" data-action="holder-filter" data-filter="${f}">${HOLDER_FILTER_LABELS[f]}</button>`).join('')}
      </div>
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th style="padding-right:28px">Holder</th><th style="padding-right:28px">Status</th><th style="text-align:right;padding-right:28px">In Inventory</th><th style="text-align:right;padding-right:28px">Ready for Pullback</th><th style="text-align:right;padding-right:28px">Lost</th><th style="text-align:right;padding-right:28px">Belcredits</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
  wireTradeItemPopovers()
}

/* — Details (Event Log) ————————————————————————————— */
let _evFilters = { asset:'', trade:'', pb:'', holder:'', victim:'', type:'ALL' }
let _evTypeGroupOpen = null
const EV_TYPE_GROUPS = [
  {label:'Trades', allValue:'ALL_TRADES', options:[
    {v:'hacked',l:'New Hacked'},
    {v:'traded',l:'New Traded'},
    {v:'gambled',l:'New Gambled'},
    {v:'earned',l:'New Earned'},
    {v:'bought',l:'New Bought (Marketplace)'},
    {v:'sold',l:'New Sold (Marketplace)'},
    {v:'friendly',l:'New Friendly Transfer'}
  ]},
  {label:'Pullbacks', allValue:'ALL_PULLBACKS', options:[
    {v:'dupe',l:'New Pullback'},
    {v:'DUPED_LOG',l:'New Duped Item'},
    {v:'pullback',l:'Marked as Pulled Back'}
  ]},
  {label:'Inventory', allValue:'ALL_INVENTORY', options:[
    {v:'NEW_ITEM',l:'New Item in Inventory'},
    {v:'LOST',l:'Marked as Lost'},
    {v:'RESTORED',l:'Marked as Restored'},
    {v:'HOLDER_CHANGE',l:'Moved'},
    {v:'EDITED',l:'Edited'}
  ]}
]
const REASON_FILTER_GROUPS = { NEW_ITEM:['CREATED','RECOVERED','IMPORTED'], LOST:['LOST'], RESTORED:['RESTORED'], HOLDER_CHANGE:['HOLDER_CHANGE'], DUPED_LOG:['DUPED_LOG'], EDITED:['EDITED'] }
const EV_TYPE_LABELS = Object.fromEntries(EV_TYPE_GROUPS.flatMap(g=>[[g.allValue,`All ${g.label}`], ...g.options.map(o=>[o.v,o.l])]))

function detailsCell(e, pbCode, linkedAssetId) {
  if (e.event_type === 'marketplace_sale') {
    const given = parseItemList(e.items_given)
    const received = e.items_received ? parseItemList(e.items_received) : []
    const bc = e.bc_amount!=null ? `<span class="text-yellow" style="font-size:10px;font-weight:700">${e.bc_amount.toLocaleString()} BC</span>` : ''
    const bcGiven = e.bc_given!=null ? `<span class="text-yellow" style="font-size:10px;font-weight:700">${e.bc_given.toLocaleString()} BC</span>` : ''
    if (!given.length && !received.length) return `${bcGiven} ${bc}` || '<span class="text-muted">—</span>'
    return `<span class="trade-items-trigger">
      <button type="button" style="background:none;border:none;padding:0;cursor:pointer;font:inherit;font-size:11px;color:var(--text);text-align:left">
        ${h(given.join(', ')||'—')}${received.length?` <span class="text-muted">→ ${h(received.join(', '))}</span>`:''}
      </button> ${bcGiven} ${bc}
      <div class="trade-items-content" hidden>
        <div style="display:flex;flex-direction:column;gap:6px">
          ${given.map(n=>tradeItemRow(n)).join('')}
          ${received.map(n=>tradeItemRow(n)).join('')}
        </div>
      </div>
    </span>`
  }
  if (e.event_type === 'dupe') {
    return `<span style="font-size:11px"><span class="text-muted">${h(e.from_holder||'—')}</span> → <strong>${h(e.to_holder||'—')}</strong>${pbCode?` <button class="link mono text-orange" style="font-size:10px" data-action="filter-events" data-key="pb" data-val="${h(pbCode)}">${h(pbCode)}</button>`:''}</span>`
  }
  if (e.event_type === 'pullback') {
    return `<span style="font-size:11px" class="text-muted">Recovered to <strong style="color:var(--text)">${h(e.to_holder||e.from_holder||'—')}</strong></span>`
  }
  if (e.reason === 'HOLDER_CHANGE') {
    return `<span style="font-size:11px"><span class="text-muted">${h(e.from_holder||'—')}</span> → <strong>${h(e.to_holder||'—')}</strong></span>`
  }
  if (e.reason === 'LOST') {
    return `<span style="font-size:11px" class="text-muted">Held by ${h(e.from_holder||'—')}</span>`
  }
  if (e.reason === 'EDITED') {
    return `<span style="font-size:11px" class="text-muted">${h(e.notes||'Edited')}</span>`
  }
  if (e.reason === 'RECOVERED') {
    // "Mark Pulled Back" + "stays in inventory" mints a fresh SS id for the recovered
    // copy, linked back to the original via linked_asset_id — without this, the new
    // id just looked like an unrelated item with no visible connection to the pullback
    // that produced it.
    return `<span style="font-size:11px" class="text-muted">Held by <strong style="color:var(--text)">${h(e.to_holder||e.from_holder||'—')}</strong>${linkedAssetId?` <span class="text-muted">· recovered from</span> <button class="link mono" style="font-size:10px" data-action="filter-events" data-key="asset" data-val="${h(linkedAssetId)}">${h(linkedAssetId)}</button>`:''}</span>`
  }
  if (['CREATED','RECOVERED','DUPED_LOG','IMPORTED','RESTORED'].includes(e.reason)) {
    return `<span style="font-size:11px" class="text-muted">Held by <strong style="color:var(--text)">${h(e.to_holder||e.from_holder||'—')}</strong></span>`
  }
  return '<span class="text-muted">—</span>'
}

async function resolveItemChain(rootId) {
  const ids = new Set([rootId])
  let frontier = [rootId]
  while (frontier.length) {
    const list = `(${frontier.join(',')})`
    const [upRes, downRes] = await Promise.all([
      sbGet(`/ss_items?select=id,linked_asset_id&id=in.${list}`).catch(()=>null),
      sbGet(`/ss_items?select=id,linked_asset_id&linked_asset_id=in.${list}`).catch(()=>null)
    ])
    const next = []
    for (const r of [...(upRes||[]), ...(downRes||[])]) {
      if (r.id && !ids.has(r.id)) { ids.add(r.id); next.push(r.id) }
      if (r.linked_asset_id && !ids.has(r.linked_asset_id)) { ids.add(r.linked_asset_id); next.push(r.linked_asset_id) }
    }
    frontier = next
  }
  return [...ids]
}

async function renderEvents(mc) {
  let q='/ss_item_events?select=id,event_type,reason,timestamp,from_holder,to_holder,scammed_user,bc_amount,bc_given,item_id,notes,items_given,items_received,scam_type,bc_counted,bc_given_counted,trade_code&order=timestamp.desc&limit=500'
  let chainIds = null, chainCodes = null
  if(_evFilters.asset){ chainIds = await resolveItemChain(_evFilters.asset); q+=`&item_id=in.(${chainIds.join(',')})` }
  if(_evFilters.trade) q+=`&trade_code=eq.${encodeURIComponent(_evFilters.trade)}`
  if(_evFilters.pb){
    const pbItems = await sbGet(`/ss_items?select=id&pb_code=eq.${encodeURIComponent(_evFilters.pb)}`) || []
    chainIds = pbItems.length ? await resolveItemChain(pbItems[0].id) : []
    q += chainIds.length ? `&item_id=in.(${chainIds.join(',')})` : `&item_id=eq.__none__`
    // Reflect the resolved asset in the Asset ID box too, not just the PB code —
    // otherwise the filter bar only shows the PB code with no obvious link to which
    // SS item it actually resolved to.
    if (pbItems.length) _evFilters.asset = pbItems[0].id
  }
  if(chainIds && chainIds.length){
    const chainItems = await sbGet(`/ss_items?select=id,pb_code&id=in.(${chainIds.join(',')})`).catch(()=>null) || []
    chainCodes = chainItems.flatMap(it=>[it.id, it.pb_code]).filter(Boolean)
  }
  if(_evFilters.holder){const hv=encodeURIComponent(_evFilters.holder);q+=`&or=(from_holder.ilike.*${hv}*,to_holder.ilike.*${hv}*)`}
  if(_evFilters.victim) q+=`&scammed_user=ilike.*${encodeURIComponent(_evFilters.victim)}*`
  if(['hacked','traded','gambled','earned','bought','sold','friendly'].includes(_evFilters.type)) q+=`&event_type=eq.marketplace_sale&scam_type=eq.${_evFilters.type}`
  else if(REASON_FILTER_GROUPS[_evFilters.type]) q+=`&event_type=eq.manual_update&reason=in.(${REASON_FILTER_GROUPS[_evFilters.type].join(',')})`
  else if(_evFilters.type==='ALL_TRADES') q+=`&event_type=eq.marketplace_sale`
  else if(_evFilters.type==='ALL_PULLBACKS') q+=`&or=(event_type.eq.dupe,event_type.eq.pullback,and(event_type.eq.manual_update,reason.eq.DUPED_LOG))`
  else if(_evFilters.type==='ALL_INVENTORY') q+=`&event_type=eq.manual_update&reason=in.(CREATED,RECOVERED,IMPORTED,LOST,RESTORED,HOLDER_CHANGE,EDITED)`
  else if(_evFilters.type&&_evFilters.type!=='ALL') q+=`&event_type=eq.${_evFilters.type}`

  const events=await sbGet(q)||[]
  window._evData={}
  for(const e of events) window._evData[e.id]=e

  const evItemIds=[...new Set(events.map(e=>e.item_id).filter(Boolean))]
  let evItemMap=new Map()
  if(evItemIds.length){const evItems=await sbGet(`/ss_items?select=id,item_name,pb_code,linked_asset_id&id=in.(${evItemIds.join(',')})`)||[];evItems.forEach(a=>evItemMap.set(a.id,a))}

  // Marks everything that happened BEFORE an item's most recent "fresh start" (New
  // Item in Inventory / Recovered Item / Imported) as old history, in red — so a
  // scan of the Logbook immediately shows what's part of the item's CURRENT cycle
  // vs. leftover history from before it last re-entered inventory.
  const genesisByItem=new Map()
  for(const e of events){
    if(['CREATED','RECOVERED','IMPORTED'].includes(e.reason)){
      const cur=genesisByItem.get(e.item_id)
      if(!cur||e.timestamp>cur) genesisByItem.set(e.item_id,e.timestamp)
    }
  }
  const isOldHistory=(itemId,ts)=>{const g=genesisByItem.get(itemId);return !!(g&&ts<g)}

  // Acquiring an item (earned/hacked/bought/received in a trade) always logs a
  // companion 'CREATED' event on top of the marketplace_sale itself — same real-world
  // moment, two rows ("New Earned" + "New Item in Inventory"). The marketplace_sale
  // row already conveys "this item now exists", so drop the redundant CREATED one.
  const acquisitionItemIds=new Set(events.filter(e=>e.event_type==='marketplace_sale').map(e=>e.item_id).filter(Boolean))

  const bulkMap=new Map(), processed=[]
  for(const e of events){
    if(e.reason==='CREATED'&&acquisitionItemIds.has(e.item_id)) continue
    if(e.reason==='DUPED_LOG') continue
    if(e.reason&&e.reason.startsWith('BULK:')){
      if(!bulkMap.has(e.reason)){bulkMap.set(e.reason,{id:e.reason,evs:[],victim:e.scammed_user,timestamp:e.timestamp,bc:e.bc_amount,from_holder:e.from_holder,items_received:e.items_received,scam_type:e.scam_type});processed.push({_bulk:true,g:bulkMap.get(e.reason)})}
      bulkMap.get(e.reason).evs.push(e)
    } else { processed.push(e) }
  }

  const rows=processed.map(entry=>{
    if(entry._bulk){
      const g=entry.g, bc=g.evs.find(e=>e.bc_amount!=null)?.bc_amount
      const given=g.evs.map(e=>e.items_given||e.item_id).filter(Boolean)
      const received=g.evs.find(e=>e.items_received)?.items_received
      const groupIsOld=g.evs.some(ev=>isOldHistory(ev.item_id,ev.timestamp))
      return `<tr${groupIsOld?' style="background:color-mix(in oklch,var(--red) 6%,transparent)"':''}>
        <td>${eventBadge('marketplace_sale',g.id,g.scam_type)}</td>
        <td><span style="font-size:10px;color:var(--muted)">${g.evs.length} items</span></td>
        <td><div style="display:flex;flex-direction:column;gap:2px"><div>${tagList(given,'--red')}</div>${received||bc!=null?`<div>→ ${tagList(received?parseItemList(received):[],'--green')} ${bc!=null?`<span class="text-yellow" style="font-size:10px;font-weight:700">${bc.toLocaleString()} BC</span>`:''}</div>`:''}</div></td>
        <td style="font-size:11px">${h(g.from_holder||'—')}</td>
        <td>${g.victim?`<span class="text-red">${h(g.victim)}</span>`:'<span class="text-muted">—</span>'}</td>
        <td class="text-muted" style="font-size:10px">${fmtDate(g.timestamp,true)}</td>
        <td></td>
      </tr>`
    }
    const e=entry
    const rowIsOld=isOldHistory(e.item_id,e.timestamp)
    return `<tr${rowIsOld?' style="background:color-mix(in oklch,var(--red) 6%,transparent)"':''}>
    <td>${eventBadge(e.event_type,e.reason,e.scam_type)}</td>
    <td>
      <button class="link mono" data-action="filter-events" data-key="asset" data-val="${h(e.item_id)}">${h(e.item_id)}</button>
      <div class="item-cell" style="margin-top:2px">${itemThumb(evItemMap.get(e.item_id)?.item_name)}<span style="font-size:10px;color:var(--muted)">${h(evItemMap.get(e.item_id)?.item_name||'—')}</span></div>
    </td>
    <td>${detailsCell(e, evItemMap.get(e.item_id)?.pb_code, evItemMap.get(e.item_id)?.linked_asset_id)}</td>
    <td style="font-size:11px">${h(e.from_holder||e.to_holder||'—')}</td>
    <td>${e.scammed_user?`<span class="text-red">${h(e.scammed_user)}</span>`:'<span class="text-muted">—</span>'}</td>
    <td class="text-muted" style="font-size:10px">${fmtDate(e.timestamp,true)}</td>
    <td><div style="display:flex;gap:4px">
      <button class="btn btn-ghost btn-sm" title="Edit" data-action="edit-event" data-id="${h(e.id)}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
      </button>
      <button class="btn btn-ghost btn-sm" title="Delete" data-action="delete-event" data-id="${h(e.id)}" style="color:var(--red)">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="12" height="12"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M9 6V4h6v2"/></svg>
      </button>
    </div></td>
  </tr>`}).join('')||'<tr class="empty-row"><td colspan="7">No events found.</td></tr>'

  mc.innerHTML=`
    <div class="page-hdr">
      <div><div class="page-title">Logbook</div><div class="page-sub">${events.length} events${_evFilters.type!=='ALL'?' · '+h(EV_TYPE_LABELS[_evFilters.type]||_evFilters.type):''}${_evFilters.holder?' · '+h(_evFilters.holder):''}${_evFilters.victim?' · '+h(_evFilters.victim):''}${_evFilters.asset?' · '+h(_evFilters.asset):''}${_evFilters.trade?' · '+h(_evFilters.trade):''}${_evFilters.pb?' · '+h(_evFilters.pb):''}</div></div>
      <button class="btn btn-outline btn-sm" data-action="clear-ev-filters">Clear filters</button>
    </div>
    ${chainCodes && chainCodes.length ? `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px;font-size:11px;color:var(--muted)">Related codes:
      ${chainCodes.map(c=>`<button class="link mono${c.startsWith('PB-')?' text-orange':''}" data-action="filter-events" data-key="${c.startsWith('PB-')?'pb':'asset'}" data-val="${h(c)}">${h(c)}</button>`).join('')}
    </div>` : ''}
    <div class="inline-filters" style="margin-bottom:10px">
      <input type="text" placeholder="Asset ID…" value="${h(_evFilters.asset)}" data-input-action="ev-asset">
      <input type="text" placeholder="Holder…"   value="${h(_evFilters.holder)}" data-input-action="ev-holder">
      <input type="text" placeholder="Victim…"   value="${h(_evFilters.victim)}" data-input-action="ev-victim">
      <button class="btn btn-primary btn-sm" data-action="apply-ev-filters">Apply</button>
    </div>
    <div class="filter-row">
      <button class="filter-chip${_evFilters.type==='ALL'?' active':''}" data-action="ev-type" data-ev-type="ALL">All</button>
      ${EV_TYPE_GROUPS.map((g,i)=>{
        const groupActive = g.options.some(o=>o.v===_evFilters.type) || _evFilters.type===g.allValue
        const open = _evTypeGroupOpen===i
        return `<span style="position:relative;display:inline-block">
          <button class="filter-chip${groupActive||open?' active':''}" data-action="ev-type-group" data-group="${i}">${h(g.label)} ▾</button>
          <div class="ac-dropdown" id="ev-type-dd-${i}" style="display:${open?'block':'none'};min-width:170px">
            <div class="ac-item" data-action="ev-type" data-ev-type="${g.allValue}" style="font-weight:700">All ${h(g.label)}</div>
            ${g.options.map(o=>`<div class="ac-item" data-action="ev-type" data-ev-type="${o.v}">${h(o.l)}</div>`).join('')}
          </div>
        </span>`
      }).join('')}
    </div>
    <div class="tbl-wrap"><table>
      <thead><tr><th>Type</th><th>Asset</th><th>Details</th><th>From</th><th>Victim</th><th>Timestamp</th><th></th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>`
  wireTradeItemPopovers()
}

