  const bg=document.getElementById('si-bc-given'); if(bg) bg.value=prevBcGiven
  const br=document.getElementById('si-bc-received'); if(br) br.value=prevBcReceived
  const n=document.getElementById('si-notes'); if(n) n.value=prevNotes
