async function loadScamImportAssets(acct) {
  window._scamImportAccount = acct
  window._scamImportGiven = new Array(SCAM_SLOT_COUNT).fill(null)
  window._scamImportPicker = null
  const dd = document.getElementById('si-account-dd'); if (dd) dd.style.display = 'none'
  try {
    const [owned, pending] = await Promise.all([
      sbGet(`/ss_items?select=id,item_name&current_status=eq.active&current_holder=ilike.${encodeURIComponent(acct)}&order=item_name`),
      sbGet(`/ss_items?select=id,item_name&current_status=eq.traded&item_holder=ilike.${encodeURIComponent(acct)}&order=item_name`)
    ])
    let availablePending = pending||[]
    if (availablePending.length) {
      const ids = availablePending.map(p=>p.id)
      const [sold, dupedCopies] = await Promise.all([
        sbGet(`/ss_item_events?select=item_id&event_type=eq.marketplace_sale&item_id=in.(${ids.join(',')})`).catch(()=>null),
        sbGet(`/ss_items?select=linked_asset_id&is_duped=eq.true&linked_asset_id=in.(${ids.join(',')})`).catch(()=>null)
      ])
      const soldIds = new Set((sold||[]).map(e=>e.item_id))
      const hasCopyIds = new Set((dupedCopies||[]).map(r=>r.linked_asset_id))
      availablePending = availablePending.filter(p=>!soldIds.has(p.id) && !hasCopyIds.has(p.id))
    }
    const seen = new Set()
    window._scamImportAssets = [...(owned||[]), ...availablePending].filter(a => seen.has(a.id) ? false : (seen.add(a.id), true))
  }
  catch(e) { window._scamImportAssets = [] }
  renderScamImportModal()
}

async function submitScamImport() {
  const acct = window._scamImportAccount
  const victim = document.getElementById('si-victim')?.value.trim()
  const bcGiven = document.getElementById('si-bc-given')?.value
  const bcReceived = document.getElementById('si-bc-received')?.value
  const notes = document.getElementById('si-notes')?.value.trim()
  const scamType = document.getElementById('si-scam-type')?.value || 'traded'
  const received = (window._scamImportReceived||[]).filter(Boolean)
  const sel = (window._scamImportGiven||[]).filter(Boolean)
  const bcToInv = document.getElementById('si-bc-to-inv')?.querySelector('.check-box')?.classList.contains('checked')
  const boughtScamType = scamType==='bought'
  const soldScamType = scamType==='sold'
  const friendlyScamType = scamType==='friendly'
  const receiveOnly = scamType==='hacked' || scamType==='earned' || boughtScamType
  if (!acct) return modalError('Select an account first.')
  if (friendlyScamType && !sel.length && !(bcGiven && Number(bcGiven)>0)) return modalError('Select at least 1 given item, or enter BC to transfer.')
  if (!received.length && receiveOnly) return modalError('Select at least 1 received item.')
  const gaveSomething = sel.length>0 || (bcGiven && Number(bcGiven)>0)
  const receivedSomething = received.length>0 || (bcReceived && Number(bcReceived)>0)
  if (!receiveOnly && !friendlyScamType && !gaveSomething && !receivedSomething) return modalError('Enter at least something given or received.')
  if (!victim && !boughtScamType && !soldScamType) return modalError('Enter a victim.')
  if (boughtScamType && !(bcGiven && Number(bcGiven)>0)) return modalError('Enter how many Belcredits you paid.')
  if (soldScamType && !(bcReceived && Number(bcReceived)>0)) return modalError('Enter how many Belcredits you received.')
  setBtn(1,'Working…',true)
  try {
    const givenAmt = bcGiven?Number(bcGiven):0
    const hasBcReceived = bcReceived && Number(bcReceived)>0
    const shouldCount = bcToInv && hasBcReceived
    const finalNotes = notesWithPersonalUseMarker(notes, hasBcReceived && !bcToInv)
    const eventId = await doBulkScam(slotsToIds(sel), boughtScamType?null:(soldScamType?'Marketplace':victim), bcReceived?Number(bcReceived):null, finalNotes, slotsToNames(received), scamType, acct, givenAmt||null)
    if (shouldCount) await addBcToInventory(acct, Number(bcReceived))
    const givenCounted = givenAmt>0
    if (givenCounted) await addBcToInventory(acct, -givenAmt)
    if (friendlyScamType && givenCounted && victim) await addBcToInventory(victim, givenAmt)
    if (eventId) await sbPatch(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}`, {bc_counted: !!shouldCount, bc_given_counted: givenCounted})
    closeModal(); nav('scammed')
  }
  catch(e) { modalError(e.message); setBtn(1,'Register Trade',false) }
}

async function addBcToInventory(holder, amount) {
  if (!holder || !amount) return
  const res = await sbGet(`/bc_balances?select=amount&holder=eq.${encodeURIComponent(holder)}`).catch(()=>null)
  const current = res?.[0]?.amount || 0
  await sbUpsert('/bc_balances?on_conflict=holder', { holder, amount: current + amount })
}

async function submitScamEdit() {
  const eventId = window._scamEditId
  const from = document.getElementById('si-account')?.value.trim()
  const victim = document.getElementById('si-victim')?.value.trim()
  const bcGiven = document.getElementById('si-bc-given')?.value
  const bcReceived = document.getElementById('si-bc-received')?.value
  const notes = document.getElementById('si-notes')?.value.trim()
  const scamType = document.getElementById('si-scam-type')?.value || 'traded'
  const given = (window._scamImportGiven||[]).filter(Boolean)
  const received = (window._scamImportReceived||[]).filter(Boolean)
  const bcToInv = document.getElementById('si-bc-to-inv')?.querySelector('.check-box')?.classList.contains('checked')
  const noVictimType = scamType==='hacked' || scamType==='earned' || scamType==='bought'
  if (!victim && !noVictimType && scamType!=='sold') return modalError('Enter a victim.')
  setBtn(1,'Saving…',true)
  try {
    const prevEv = window._evData?.[eventId] || {}
    const oldReceived = parseItemList(prevEv.items_received)
    const newBcAmount = bcReceived?Number(bcReceived):0
    const givenNames = slotsToNames(given), receivedNames = slotsToNames(received)
    const isFriendlyEdit = scamType==='friendly'
    const shouldCount = bcToInv && newBcAmount>0
    const finalNotes = notesWithPersonalUseMarker(notes, newBcAmount>0 && !bcToInv)
    await sbPatch(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}`, {
      from_holder: from||null,
      scammed_user: isFriendlyEdit?null:(scamType==='sold'?'Marketplace':(victim||null)),
      to_holder: isFriendlyEdit?(victim||null):null,
      bc_amount: bcReceived?Number(bcReceived):null,
      bc_given: bcGiven?Number(bcGiven):null,
      items_given: givenNames.join(', ')||null,
      items_received: receivedNames.join(', ')||null,
      scam_type: scamType,
      notes: finalNotes
    })
    if (window._scamEditNotesItemId) await sbPatch(`/ss_items?id=eq.${encodeURIComponent(window._scamEditNotesItemId)}`, {notes: finalNotes})
    await reconcileReceivedItems(prevEv.trade_code||eventId, from, oldReceived, receivedNames)
    const bcCounted = await reconcileBcBalance(eventId, from, prevEv, bcToInv, newBcAmount)
    const newBcGivenAmount = bcGiven?Number(bcGiven):0
    const bcGivenCounted = await reconcileBcGivenBalance(eventId, from, prevEv, newBcGivenAmount)
    await sbPatch(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}`, {bc_counted: bcCounted, bc_given_counted: bcGivenCounted})
    if (prevEv.item_id) await sbPost('/ss_item_events',{item_id:prevEv.item_id,event_type:'manual_update',reason:'EDITED',from_holder:from||null,notes:'Trade edited'})
    await invalidateDashboardHistory()
    closeModal(); route()
  } catch(e) { modalError(e.message); setBtn(1,'Save',false) }
}

async function reconcileBcBalance(eventId, holder, prevEv, wantCounted, newAmount) {
  const wasCounted = !!prevEv.bc_counted
  const prevAmount = prevEv.bc_amount || 0
  if (!holder) return false
  if (wantCounted && !wasCounted) {
    if (newAmount>0) await addBcToInventory(holder, newAmount)
    return newAmount>0
  }
  if (!wantCounted && wasCounted) {
    if (prevAmount>0) await addBcToInventory(holder, -prevAmount)
    return false
  }
  if (wantCounted && wasCounted && newAmount!==prevAmount) {
    const delta = newAmount-prevAmount
    if (delta) await addBcToInventory(holder, delta)
    return newAmount>0
  }
  return wasCounted
}

async function reconcileBcGivenBalance(eventId, holder, prevEv, newAmount) {
  const wasCounted = !!prevEv.bc_given_counted
  const prevAmount = prevEv.bc_given || 0
  const wantCounted = newAmount > 0
  if (!holder) return false
  if (wantCounted && !wasCounted) {
    await addBcToInventory(holder, -newAmount)
    return true
  }
  if (!wantCounted && wasCounted) {
    if (prevAmount>0) await addBcToInventory(holder, prevAmount)
    return false
  }
  if (wantCounted && wasCounted && newAmount!==prevAmount) {
    const delta = newAmount-prevAmount
    if (delta) await addBcToInventory(holder, -delta)
    return true
  }
  return wasCounted
}

async function reconcileReceivedItems(tradeCode, holder, oldReceived, newReceived) {
  const oldCount = new Map()
  for (const n of oldReceived) oldCount.set(n, (oldCount.get(n)||0)+1)
  const newCount = new Map()
  for (const n of newReceived) newCount.set(n, (newCount.get(n)||0)+1)

  const toAdd = []
  for (const [n,c] of newCount) { const extra = c-(oldCount.get(n)||0); for (let i=0;i<extra;i++) toAdd.push(n) }
  const toRemove = []
  for (const [n,c] of oldCount) { const extra = c-(newCount.get(n)||0); for (let i=0;i<extra;i++) toRemove.push(n) }

  if (toRemove.length) {
    const tag = `Received from trade #${tradeCode}`
    const candidates = await sbGet(`/ss_items?select=id,item_name&notes=eq.${encodeURIComponent(tag)}&current_status=eq.active`).catch(()=>null)
    for (const name of toRemove) {
      const match = (candidates||[]).find(c=>c.item_name===name)
      if (match) { await doDeleteAsset(match.id); candidates.splice(candidates.indexOf(match),1) }
    }
  }
  if (toAdd.length && holder) await materializeReceivedItems(holder, toAdd, tradeCode)
}

