const SCAM_TYPE_LABELS = {hacked:'Hacked', traded:'Traded', gambled:'Gambled', earned:'Earned', bought:'Bought from Marketplace', sold:'Sold on Marketplace', friendly:'Friendly Transfer'}
const SCAM_TYPE_COLORS = {hacked:'var(--green)', traded:'var(--red)', gambled:'var(--red)', earned:'var(--green)', bought:'var(--green)', sold:'var(--red)', friendly:'var(--green)'}
function scamTypeField(id) {
  return `<div class="form-group"><label>Type *</label>
    <select id="${id}"><option value="traded">Traded</option><option value="gambled">Gambled</option><option value="hacked">Hacked</option><option value="earned">Earned</option></select>
  </div>`
}
function tradeScamTypeField(id, currentType) {
  const opts = [{v:'traded',l:'Traded'},{v:'gambled',l:'Gambled'},{v:'bought',l:'Bought from Marketplace'},{v:'sold',l:'Sold on Marketplace'},{v:'friendly',l:'Friendly Transfer'}]
  if (currentType && !opts.some(o=>o.v===currentType)) opts.unshift({v:currentType,l:SCAM_TYPE_LABELS[currentType]||currentType})
  return `<div class="form-group"><label>Type *</label>
    <select id="${id}">${opts.map(o=>`<option value="${o.v}">${h(o.l)}</option>`).join('')}</select>
  </div>`
}

