async function doDeleteEvent(eventId) {
  const res = await sbGet(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}&select=item_id,reason,event_type,scam_type,trade_code,bc_amount,bc_given,bc_counted,bc_given_counted,from_holder,to_holder`)
  const ev = res?.[0]
  if (!ev || ev.event_type !== 'marketplace_sale') {
    // Deleting a "Moved" log row used to just remove the row — the item's
    // current_holder stayed at whatever that event had set, silently drifting out of
    // sync with a Logbook that no longer showed how it got there. Revert it too, but
    // only if nothing newer already moved the item on (current_holder still matches
    // this event's own "to").
    if (ev && (ev.reason==='HOLDER_CHANGE'||ev.reason==='EDITED') && ev.item_id && ev.to_holder) {
      const cur = await sbGet(`/ss_items?id=eq.${encodeURIComponent(ev.item_id)}&select=current_holder`)
      if (cur?.[0]?.current_holder === ev.to_holder) {
        await sbPatch(`/ss_items?id=eq.${encodeURIComponent(ev.item_id)}`, { current_holder: ev.from_holder||null })
      }
    }
    await sbDel(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}`); return
  }

  const materialized = await sbGet(`/ss_items?select=id&notes=eq.${encodeURIComponent('Received from trade #'+(ev.trade_code||eventId))}`).catch(()=>null) || []
  for (const m of materialized) await doDeleteAsset(m.id)

  const isAcquisitionType = ev.scam_type==='hacked' || ev.scam_type==='earned' || ev.scam_type==='bought'
  if (isAcquisitionType) {
    if (ev.item_id) {
      const stillThere = await sbGet(`/ss_items?id=eq.${encodeURIComponent(ev.item_id)}&select=id`).catch(()=>null)
      if (stillThere?.length) await doDeleteAsset(ev.item_id)
    }
  } else {
    const batchEvents = ev.reason
      ? await sbGet(`/ss_item_events?select=item_id&reason=eq.${encodeURIComponent(ev.reason)}&event_type=eq.marketplace_sale`).catch(()=>null)
      : null
    const givenItemIds = batchEvents?.length ? batchEvents.map(e=>e.item_id) : (ev.item_id ? [ev.item_id] : [])
    for (const itemId of givenItemIds) {
      if (!itemId) continue
      const itemRes = await sbGet(`/ss_items?id=eq.${encodeURIComponent(itemId)}&select=current_status,item_holder`)
      const item = itemRes?.[0]
      if (!item) continue
      if (ev.scam_type==='friendly') {
        if (ev.from_holder) await sbPatch(`/ss_items?id=eq.${encodeURIComponent(itemId)}`, {current_holder:ev.from_holder})
      } else if (item.current_status==='traded' && !item.item_holder) {
        await sbPatch(`/ss_items?id=eq.${encodeURIComponent(itemId)}`, {current_status:'active', count_in_inventory:true})
      }
    }
  }

  if (ev.bc_counted && ev.bc_amount) await addBcToInventory(ev.from_holder, -ev.bc_amount)
  if (ev.bc_given_counted && ev.bc_given) await addBcToInventory(ev.from_holder, ev.bc_given)

  if (ev.reason) await sbDel(`/ss_item_events?reason=eq.${encodeURIComponent(ev.reason)}`)
  else await sbDel(`/ss_item_events?id=eq.${encodeURIComponent(eventId)}`)
}

function openSeedSSItemsModal() {
  openModal('Import SS Items',`
    <p style="font-size:12px;color:var(--muted);margin-bottom:14px">Creates <strong>${SS_ITEM_NAMES.length}</strong> assets — one per SS item. You can set the holder per asset afterwards.</p>
    <div class="form-group"><label>Default Holder (optional)</label><input type="text" id="m-holder" placeholder="Username or leave empty" autofocus></div>`,
  [{label:'Cancel',fn:closeModal},{label:`Import ${SS_ITEM_NAMES.length} items`,cls:'btn-primary',fn:async()=>{
    const holder=document.getElementById('m-holder').value.trim()||'Unknown'
    setBtn(1,'Working…',true)
    try{
      const existing=await sbGet('/ss_items?select=item_name')||[]
      const existingNames=new Set(existing.map(x=>x.item_name))
      const toAdd=SS_ITEM_NAMES.filter(n=>!existingNames.has(n))
      if(!toAdd.length){closeModal();return}
      const baseId=await generateAssetId()
      const baseNum=parseInt(String(baseId).replace('SS-',''),10)
      for(let i=0;i<toAdd.length;i++){
        const id='SS-'+String(baseNum+i).padStart(4,'0')
        await sbPost('/ss_items',{id,item_name:toAdd[i],current_holder:holder,current_status:'active',count_in_inventory:true,notes:null})
        await sbPost('/ss_item_events',{item_id:id,event_type:'manual_update',reason:'IMPORTED',to_holder:holder,notes:'Imported from leet_furni.json'})
        if(i%20===0) setBtn(1,`${i}/${toAdd.length}…`,true)
      }
      closeModal();nav('inventory')
    }catch(e){modalError(e.message);setBtn(1,`Import ${SS_ITEM_NAMES.length} items`,false)}
  }}])
}

