/* — Mutations ——————————————————————————————————— */
async function doCreateAsset(itemName, holder, notes, acquiredVia, hackedFrom, bc) {
  const id=await generateAssetId()
  await sbPost('/ss_items',{id,item_name:itemName,current_holder:holder,current_status:'active',count_in_inventory:true,is_duped:acquiredVia==='duped',acquired_via:acquiredVia||null,notes:notes||null})
  await sbPost('/ss_item_events',{item_id:id,event_type:'manual_update',reason:'CREATED',to_holder:holder,notes:notes||null})
  const bcCounted = bc>0
  await sbPost('/ss_item_events',{item_id:id,event_type:'marketplace_sale',from_holder:acquiredVia==='hacked'?(hackedFrom||null):null,items_received:itemName,bc_amount:bc||null,bc_counted:bcCounted,scam_type:acquiredVia==='hacked'?'hacked':'earned',notes:notes||null})
  if (bcCounted) await addBcToInventory(holder, bc)
}

async function doCreatePullbackAsset(assetId, itemName, pullbackHolder, itemHolder, notes) {
  // If the account that's supposed to be physically holding this (itemHolder) is
  // already banned, there's no realistic path to recover it — creating a fresh
  // "active, trackable" duped copy under a banned account (as doBanHolder never ran
  // against an item that didn't exist yet at ban time) just leaves a phantom
  // available-looking item sitting there forever. Both halves start Lost instead.
  const bannedRows = await sbGet('/banned_holders?select=holder').catch(()=>null) || []
  const bannedSet = new Set(bannedRows.map(r=>(r.holder||'').toLowerCase()))
  const itemHolderBanned = isBanned(bannedSet, itemHolder)

  const pbCode = await generatePbCode()
  const claimStatus = itemHolderBanned ? 'lost' : 'traded'
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`, {item_holder:itemHolder,current_status:claimStatus,count_in_inventory:false,notes:notes||null,pb_code:pbCode})
  await sbPost('/ss_item_events',{item_id:assetId,event_type:'dupe',from_holder:pullbackHolder,to_holder:itemHolder,notes:notes||null})
  // "(was: traded)" matches the same pattern doUnbanHolder looks for, so unbanning
  // itemHolder later auto-restores this claim instead of leaving it stuck Lost.
  if (itemHolderBanned) await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'LOST',from_holder:itemHolder,notes:`Item Holder ${itemHolder} already banned at pullback creation (was: traded)`})

  const dupedId=await generateAssetId()
  const dupedStatus = itemHolderBanned ? 'lost' : 'active'
  await sbPost('/ss_items',{id:dupedId,item_name:itemName,current_holder:itemHolder,current_status:dupedStatus,count_in_inventory:!itemHolderBanned,is_duped:true,linked_asset_id:assetId,notes:`Duped copy of ${assetId}`})
  await sbPost('/ss_item_events',{item_id:dupedId,event_type:'manual_update',reason:'DUPED_LOG',to_holder:itemHolder,notes:`Duped copy of ${assetId}`})
  if (itemHolderBanned) await sbPost('/ss_item_events',{item_id:dupedId,event_type:'manual_update',reason:'LOST',from_holder:itemHolder,notes:`Item Holder ${itemHolder} already banned at pullback creation (was: active)`})
}

async function doChangeHolder(assetId, newHolder, notes) {
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder`)
  const prev=res?.[0]?.current_holder
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`,{current_holder:newHolder})
  // Logged as EDITED, not a "Moved"/trade-flavored event — Change Holder is a manual
  // correction tool (typos, admin fixes), not how a real transfer between two accounts
  // should be recorded (that's Friendly Transfer, which properly logs a trade). Calling
  // it "Moved" made a plain data fix look like an actual in-game handoff happened.
  const combinedNotes=[`Holder: ${prev||'—'} → ${newHolder}`, notes||null].filter(Boolean).join(' | ')
  await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'EDITED',from_holder:prev||null,to_holder:newHolder,notes:combinedNotes})
}

async function doEditAsset(assetId, newHolder, newStatus, notes, newDuped, newItemHolder, staysInInventory, personalUseNote) {
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder,current_status,item_holder,notes`)
  const prev=res?.[0]||{}
  const holderChanged = newHolder && newHolder!==prev.current_holder
  const itemHolderChanged = newItemHolder !== undefined && newItemHolder !== (prev.item_holder||'')
  const statusChanged = newStatus && newStatus!==prev.current_status
  const notesChanged = notes !== undefined && notes !== (prev.notes||'')
  const patch = {}
  if (holderChanged) patch.current_holder = newHolder
  if (itemHolderChanged) patch.item_holder = newItemHolder || null
  if (statusChanged) { patch.current_status = newStatus; patch.count_in_inventory = newStatus!=='lost' }
  if (newDuped !== undefined) patch.is_duped = newDuped
  if (notesChanged) patch.notes = notes || null
  if (Object.keys(patch).length) await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`, patch)
  let logged = false
  if (holderChanged) { await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'HOLDER_CHANGE',from_holder:prev.current_holder||null,to_holder:newHolder,notes:notes||null}); logged = true }

  if (itemHolderChanged && newItemHolder) {
    const copyRes = await sbGet(`/ss_items?select=id&linked_asset_id=eq.${encodeURIComponent(assetId)}&is_duped=eq.true`)
    const copyId = copyRes?.[0]?.id
    if (copyId) await sbPatch(`/ss_items?id=eq.${encodeURIComponent(copyId)}`, {current_holder:newItemHolder})
  }

  const isPullbackSave = newStatus==='pullbacked' && (statusChanged || prev.current_status==='pullbacked')
  if (isPullbackSave) {
    const recoveredHolder = newHolder || prev.current_holder
    const kept = staysInInventory !== false
    const personalNote = personalUseNote || 'Pulled back for personal use'
    const base = (notes || prev.notes || '').split(' | ').map(s=>s.trim()).filter(s=>s && s!==personalNote)
    if (!kept) base.push(personalNote)
    const finalNotes = base.join(' | ') || null
    await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`, {notes: finalNotes})

    if (statusChanged) {
      await sbPost('/ss_item_events',{item_id:assetId,event_type:'pullback',from_holder:prev.current_holder||null,to_holder:recoveredHolder,notes:finalNotes})
      logged = true
    }

    const existingRecRes = await sbGet(`/ss_items?select=id&linked_asset_id=eq.${encodeURIComponent(assetId)}&acquired_via=eq.pullback`)
    const existingRecId = existingRecRes?.[0]?.id
    if (kept && !existingRecId) {
      const recId = await generateAssetId()
      const assetRes = await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=item_name`)
      const itemName = assetRes?.[0]?.item_name
      await sbPost('/ss_items',{id:recId,item_name:itemName,current_holder:recoveredHolder,current_status:'active',count_in_inventory:true,is_duped:false,acquired_via:'pullback',linked_asset_id:assetId,notes:`Recovered from pullback ${assetId}`})
      await sbPost('/ss_item_events',{item_id:recId,event_type:'manual_update',reason:'RECOVERED',to_holder:recoveredHolder,notes:`Recovered from pullback ${assetId}`})
    } else if (!kept && existingRecId) {
      await doDeleteAsset(existingRecId)
    }
  }
  else if (statusChanged) {
    if (newStatus==='lost') { await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'LOST',from_holder:prev.current_holder||null,notes:notes||null}); logged = true }
    else if (newStatus==='active') { await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'RESTORED',to_holder:newHolder||prev.current_holder||null,notes:notes||'Restored'}); logged = true }
  }

  if (!logged && (itemHolderChanged || newDuped !== undefined || notesChanged)) {
    await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'EDITED',from_holder:prev.current_holder||null,notes:notes||null})
  }
  if (statusChanged || holderChanged) await invalidateDashboardHistory()
}

async function doScam(assetId, victim, bc, notes, itemsGiven, itemsReceived, scamType) {
  const isBought = scamType==='bought'
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder,item_name,acquired_via`)
  const prev=res?.[0]||{}
  const acquiredVia = isBought ? 'bought' : null
  const tradeCode = (isBought || prev.acquired_via==='bought') ? null : await generateTradeCode()
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`,{current_status:'traded'})
  const given=[prev.item_name,...(itemsGiven||[])].filter(Boolean)
  const createdEv = await sbPost('/ss_item_events',{item_id:assetId,event_type:'marketplace_sale',trade_code:tradeCode,from_holder:prev.current_holder||null,scammed_user:victim,bc_amount:bc,notes:notes||null,items_given:given.join(', ')||null,items_received:(itemsReceived||[]).join(', ')||null,scam_type:scamType||'traded'})
  if (prev.current_holder) await materializeReceivedItems(prev.current_holder, itemsReceived, tradeCode, acquiredVia)
}

async function doPullback(assetId, notes) {
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder`)
  const prev=res?.[0]?.current_holder
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`,{current_status:'active',count_in_inventory:true})
  await sbPost('/ss_item_events',{item_id:assetId,event_type:'pullback',from_holder:prev||null,notes:notes||null})
}

async function doMarkLost(assetId, notes) {
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder`)
  const prev=res?.[0]?.current_holder
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`,{current_status:'lost',count_in_inventory:false})
  await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'LOST',from_holder:prev||null,notes:notes||null})
}

async function doDeleteAsset(assetId) {
  const linked = await sbGet(`/ss_items?select=id&linked_asset_id=eq.${encodeURIComponent(assetId)}`).catch(()=>null) || []
  for (const l of linked) {
    await sbDel(`/ss_item_events?item_id=eq.${encodeURIComponent(l.id)}`)
    await sbDel(`/ss_items?id=eq.${encodeURIComponent(l.id)}`)
  }
  await sbDel(`/ss_item_events?item_id=eq.${encodeURIComponent(assetId)}`)
  await sbDel(`/ss_items?id=eq.${encodeURIComponent(assetId)}`)
  await invalidateDashboardHistory()
}

async function doBanHolder(holder) {
  await sbUpsert('/banned_holders?on_conflict=holder', { holder })
  const items = await sbGet(`/ss_items?select=id,current_status,is_duped,item_holder&current_holder=eq.${encodeURIComponent(holder)}&current_status=in.(active,pullbacked,traded)`) || []
  for (const item of items) {
    // current_holder on a pullback claim is whoever is TRACKING the recovery, not who
    // physically has the item — that's item_holder. Banning the tracker shouldn't mark
    // the item Lost when it's still genuinely sitting in someone else's real inventory,
    // untouched by this ban (already skipped duped claims in 'traded'; a non-duped
    // claim with item_holder set is the exact same situation and was wrongly missed).
    if (item.item_holder) continue
    if (item.is_duped && item.current_status === 'traded') continue
    await doMarkLost(item.id, `Account banned (was: ${item.current_status})`)
  }
}

async function doUnbanHolder(holder) {
  await sbDel(`/banned_holders?holder=eq.${encodeURIComponent(holder)}`)
  const items = await sbGet(`/ss_items?select=id&current_holder=eq.${encodeURIComponent(holder)}&current_status=eq.lost`) || []
  for (const item of items) {
    const evs = await sbGet(`/ss_item_events?item_id=eq.${encodeURIComponent(item.id)}&reason=eq.LOST&order=timestamp.desc&limit=1&select=notes`) || []
    const m = evs[0]?.notes?.match(/was: (\w+)/)
    if (!m) continue
    await doRestore(item.id, 'Restored after unban', m[1])
  }
}

async function doRenameHolder(oldName, newName) {
  const enc = encodeURIComponent(oldName), encNew = encodeURIComponent(newName)
  await sbPatch(`/ss_items?current_holder=eq.${enc}`, {current_holder:newName})
  await sbPatch(`/ss_items?item_holder=eq.${enc}`, {item_holder:newName})
  await sbPatch(`/ss_item_events?from_holder=eq.${enc}`, {from_holder:newName})
  await sbPatch(`/ss_item_events?to_holder=eq.${enc}`, {to_holder:newName})
  await sbPatch(`/ss_item_events?scammed_user=eq.${enc}`, {scammed_user:newName})

  const [oldBc, newBc] = await Promise.all([
    sbGet(`/bc_balances?select=amount&holder=eq.${enc}`).catch(()=>null),
    sbGet(`/bc_balances?select=amount&holder=eq.${encNew}`).catch(()=>null)
  ])
  const oldAmt = oldBc?.[0]?.amount
  if (oldAmt != null) {
    await sbUpsert('/bc_balances?on_conflict=holder', {holder:newName, amount:(newBc?.[0]?.amount||0)+oldAmt})
    await sbDel(`/bc_balances?holder=eq.${enc}`)
  }

  const oldBanned = await sbGet(`/banned_holders?select=holder&holder=eq.${enc}`).catch(()=>null)
  if (oldBanned?.length) {
    await sbUpsert('/banned_holders?on_conflict=holder', {holder:newName})
    await sbDel(`/banned_holders?holder=eq.${enc}`)
  }

  await invalidateDashboardHistory()
}

async function doRestore(assetId, notes, status) {
  const res=await sbGet(`/ss_items?id=eq.${encodeURIComponent(assetId)}&select=current_holder`)
  const prev=res?.[0]?.current_holder
  const newStatus = status || 'active'
  await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`,{current_status:newStatus,count_in_inventory:newStatus==='active'||newStatus==='pullbacked'})
  await sbPost('/ss_item_events',{item_id:assetId,event_type:'manual_update',reason:'RESTORED',to_holder:prev||null,notes:notes||'Restored'})
}

async function materializeReceivedItems(holder, items, sourceTradeCode, acquiredVia) {
  const tag = acquiredVia==='bought' ? 'Bought from Marketplace' : (sourceTradeCode ? `Received from trade #${sourceTradeCode}` : 'Received from scam')
  const createdIds = []
  for (const name of (items||[])) {
    if (!SS_ITEM_NAMES.includes(name)) continue
    const id = await generateAssetId()
    const extra = acquiredVia ? {acquired_via:acquiredVia} : {}
    await sbPost('/ss_items',{id,item_name:name,current_holder:holder,current_status:'active',count_in_inventory:true,is_duped:false,notes:tag,...extra})
    await sbPost('/ss_item_events',{item_id:id,event_type:'manual_update',reason:'CREATED',to_holder:holder,notes:tag})
    createdIds.push(id)
  }
  return createdIds
}

async function doBulkScam(assetIds, victim, bc, notes, itemsReceived, scamType, acct, bcGiven) {
  const batchId='BULK:BS'+Date.now()
  const recvStr=(itemsReceived||[]).join(', ')||null
  let fromHolder = acct
  const isFriendly = scamType==='friendly'
  const isBought = scamType==='bought'
  const acquiredVia = isBought ? 'bought' : null

  if (!assetIds.length) {
    if (!fromHolder) return null
    const tradeCode = isBought ? null : await generateTradeCode()
    const createdIds = await materializeReceivedItems(fromHolder, itemsReceived, tradeCode, acquiredVia)
    const anchorId = createdIds[0]
    const noSourceFrom = scamType==='earned' || isBought
    if (anchorId) {
      const createdEv = await sbPost('/ss_item_events',{item_id:anchorId,event_type:'marketplace_sale',trade_code:tradeCode,from_holder:noSourceFrom?null:fromHolder,to_holder:isFriendly?victim:null,scammed_user:isFriendly?null:victim,bc_amount:bc,bc_given:bcGiven,notes:notes||null,items_given:null,items_received:recvStr,scam_type:scamType||'traded'})
      return createdEv?.[0]?.id
    }
    if (bc==null && bcGiven==null) return null
    const createdEv = await sbPost('/ss_item_events',{item_id:null,event_type:'marketplace_sale',trade_code:tradeCode,from_holder:noSourceFrom?null:fromHolder,to_holder:isFriendly?victim:null,scammed_user:isFriendly?null:victim,bc_amount:bc,bc_given:bcGiven,notes:notes||null,items_given:null,items_received:null,scam_type:scamType||'traded'})
    return createdEv?.[0]?.id
  }

  const givenRes = await sbGet(`/ss_items?select=id,current_holder,item_name,acquired_via&id=in.(${assetIds.join(',')})`) || []
  const givenMap = new Map(givenRes.map(a=>[a.id,a]))
  const isResoldBought = assetIds.some(id => givenMap.get(id)?.acquired_via==='bought')
  const tradeCode = (isBought || isResoldBought) ? null : await generateTradeCode()

  let primaryEventId = null
  for(let i=0;i<assetIds.length;i++){
    const assetId=assetIds[i]
    const prev=givenMap.get(assetId)||{}
    if (!fromHolder) fromHolder = prev.current_holder
    await sbPatch(`/ss_items?id=eq.${encodeURIComponent(assetId)}`, isFriendly ? {current_holder:victim} : {current_status:'traded'})
    const createdEv = await sbPost('/ss_item_events',{item_id:assetId,event_type:'marketplace_sale',reason:batchId,trade_code:tradeCode,from_holder:acct||prev.current_holder||null,to_holder:isFriendly?victim:null,scammed_user:isFriendly?null:victim,bc_amount:i===0?bc:null,bc_given:i===0?bcGiven:null,notes:notes||null,items_given:prev.item_name||null,items_received:i===0?recvStr:null,scam_type:scamType||'traded'})
    if (i===0) primaryEventId = createdEv?.[0]?.id
  }
  if (fromHolder) await materializeReceivedItems(fromHolder, itemsReceived, tradeCode, acquiredVia)
  return primaryEventId
}

async function doClearDatabase() {
  await sbDel('/ss_item_events?id=not.is.null')
  await sbDel('/ss_trade_items?id=not.is.null')
  await sbDel('/ss_trades?id=not.is.null')
  await sbDel('/ss_items?id=not.is.null')
  await sbDel('/bc_balances?holder=not.is.null').catch(()=>{})
  await invalidateDashboardHistory()
}

