let _tutScope = null, _tutSteps = [], _tutStep = 0, _tutLastOnEnterFn = null

function openTutorialPicker() {
  const chapterBtns = TUTORIAL_CHAPTERS.map(c =>
    `<button class="btn btn-outline" style="width:100%;text-align:left;padding:10px 12px;margin-bottom:6px;display:block" data-action="start-tutorial" data-tut="${c.id}">
      <div style="font-weight:700;font-size:13px">${h(c.label)}</div>
    </button>`
  ).join('')
  openModal('Tutorials', `
    <button class="btn btn-primary" style="width:100%;text-align:left;padding:12px;margin-bottom:14px;display:block" data-action="start-tutorial" data-tut="full">
      <div style="font-weight:700;font-size:13px">Hele tutorial</div>
      <div style="font-size:11px;margin-top:2px;opacity:.85">Loopt door elke tab heen, stap voor stap.</div>
    </button>
    <div style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px">Of ga direct naar een hoofdstuk</div>
    <div>${chapterBtns}</div>`,
  [{label:'Sluiten', fn:closeModal}])
}

async function startTutorial(scope) {
  closeModal()
  _tutScope = scope
  _tutSteps = scope === 'full' ? TUTORIAL_STEPS : TUTORIAL_STEPS.filter(s=>s.chapter===scope)
  _tutStep = 0
  _tutLastOnEnterFn = null
  await showTutorialStep()
}

async function waitForElement(selector, timeoutMs = 3000) {
  if (!selector) return null
  const start = Date.now()
  while (Date.now() - start < timeoutMs) {
    const el = document.querySelector(selector)
    if (el) return el
    await new Promise(r => setTimeout(r, 40))
  }
  return document.querySelector(selector)
}

async function showTutorialStep() {
  const step = _tutSteps[_tutStep]
  if (!step) { endTutorial(); return }
  const stepAtStart = _tutStep
  const sameFormAsLastStep = step.onEnter && step.onEnter === _tutLastOnEnterFn
  if (!sameFormAsLastStep) closeModal()
  const currentRoute = (window.location.hash.slice(1)||'dashboard').split('/')[0]
  if (step.route && step.route !== currentRoute) nav(step.route)
  if (step.onEnter && !sameFormAsLastStep) await step.onEnter()
  _tutLastOnEnterFn = step.onEnter || null
  if (step.target) await waitForElement(step.target)
  else await new Promise(r => setTimeout(r, 80))
  if (_tutStep !== stepAtStart) return
  positionTutorialStep(step)
}

function positionTutorialStep(step) {
  const overlay = document.getElementById('tutorial-overlay')
  const spotlight = document.getElementById('tutorial-spotlight')
  const card = document.getElementById('tutorial-card')
  const chapterLabel = TUTORIAL_CHAPTERS.find(c=>c.id===step.chapter)?.label

  document.getElementById('tutorial-progress').textContent = `${chapterLabel?chapterLabel+' — ':''}Stap ${_tutStep+1} van ${_tutSteps.length}`
  document.getElementById('tutorial-title').textContent = step.title
  document.getElementById('tutorial-text').textContent = step.text
  document.getElementById('tutorial-prev-btn').style.visibility = _tutStep===0 ? 'hidden' : 'visible'
  document.getElementById('tutorial-next-btn').textContent = _tutStep===_tutSteps.length-1 ? 'Klaar' : 'Volgende'

  const target = step.target ? document.querySelector(step.target) : null
  if (target) {
    target.scrollIntoView({block:'center'})
    const r = target.getBoundingClientRect()
    const pad = 6
    spotlight.style.display = 'block'
    spotlight.style.left = (r.left-pad)+'px'
    spotlight.style.top = (r.top-pad)+'px'
    spotlight.style.width = (r.width+pad*2)+'px'
    spotlight.style.height = (r.height+pad*2)+'px'
    overlay.classList.remove('no-target')

    const cardW = 320
    let left = Math.min(Math.max(r.left, 12), window.innerWidth-cardW-12)
    let top = r.bottom + 16
    if (top + 200 > window.innerHeight) top = Math.max(12, r.top - 200)
    card.style.transform = 'none'
    card.style.left = left+'px'
    card.style.top = top+'px'
  } else {
    spotlight.style.display = 'none'
    overlay.classList.add('no-target')
    card.style.left = '50%'
    card.style.top = '50%'
    card.style.transform = 'translate(-50%,-50%)'
  }
  overlay.classList.add('open')
}

function tutorialNext() {
  if (!_tutSteps.length) return
  if (_tutStep >= _tutSteps.length-1) { endTutorial(); return }
  _tutStep++
  showTutorialStep()
}
function tutorialPrev() {
  if (_tutStep <= 0) return
  _tutStep--
  showTutorialStep()
}
function endTutorial() {
  _tutScope = null
  _tutSteps = []
  _tutLastOnEnterFn = null
  closeModal()
  const overlay = document.getElementById('tutorial-overlay')
  overlay.classList.remove('open')
  overlay.classList.remove('no-target')
}

/* — Init ————————————————————————————————————— */
window.addEventListener('hashchange', route)
window.addEventListener('load', () => { setupEvents(); route() })
